update conditions set description = $c$Enzarzado en una lucha o algún otro tipo de forcejeo con uno o más atacantes. Un personaje apresado sólo puede llevar a cabo una serie limitada de acciones, no amenaza ninguna área y pierde su bonificador de Destreza a la CA contra los oponentes que no estén participando en la presa. En el caso de las criaturas, la presa puede indicar que el monstruo atrapa a su oponente de alguna forma (con sus fauces, bajo una enorme pata, etc.).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'apresado';
