update conditions set description = $c$Desconcertado e incapaz de decidirse a actuar por culpa de un conjuro o efecto mágico. Las acciones de un personaje confuso se determinan lanzando d% al principio de su turno: 01-10, ataca al lanzador con armas de cuerpo a cuerpo o a distancia (o se acerca a este, si no le es posible atacarlo); 11-20, actúa de forma normal; 21-50, no hace nada más que balbucear de manera incoherente; 51-70, se aleja del lanzador a la mayor velocidad posible; 71-100, ataca a la criatura más cercana (en este caso, un familiar cuenta como parte del propio individuo). Un personaje confuso que no pueda llevar a cabo la acción indicada permanecerá sin hacer nada salvo balbucear de manera incoherente. Los atacantes no obtienen ninguna ventaja especial al atacar a un personaje confuso. Cualquier personaje confuso que sea atacado atacará automáticamente a sus atacantes cuando llegue su turno. Un personaje confuso no realiza ataques de oportunidad contra criaturas a las que no esté ya dedicándose a atacar (por ser esta su acción más reciente o porque acaba de ser atacado por ellas).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'confuso';
insert into conditions (name, name_en, description, source)
