where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'despavorido');
update conditions set description = $c$Especialmente vulnerable a los ataques al comienzo de un combate. Los personajes se consideran desprevenidos hasta que llega su primer turno en el ciclo de iniciativa. Las criaturas desprevenidas no pueden usar su bonif. de Des a la CA ni efectuar ataques de oportunidad.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'desprevenido';
