update conditions set description = $c$Enredado. Estar enmarañado impide el movimiento, pero no lo hace por completo a no ser que las ligaduras estén atadas a un objeto inmóvil o retenidas por una fuerza que se oponga al movimiento. Una criatura enmarañada se mueve a la mitad de velocidad, no puede correr ni cargar y, además, sufre un -2 en las tiradas de ataque y un -4 en su puntuación efectiva de Destreza. Un personaje enmarañado que intente lanzar un conjuro debe realizar una prueba de Concentración (CD 15 + el nivel del conjuro) o perderlo.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'enmaranado';
insert into conditions (name, name_en, description, source)
select $c$Enmarañado$c$, $c$$c$, $c$Enredado. Estar enmarañado impide el movimiento, pero no lo hace por completo a no ser que las ligaduras estén atadas a un objeto inmóvil o retenidas por una fuerza que se oponga al movimiento. Una criatura enmarañada se mueve a la mitad de velocidad, no puede correr ni cargar y, además, sufre un -2 en las tiradas de ataque y un -4 en su puntuación efectiva de Destreza. Un personaje enmarañado que intente lanzar un conjuro debe realizar una prueba de Concentración (CD 15 + el nivel del conjuro) o perderlo.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'enmaranado');
