update conditions set description = $c$Cansado hasta el punto de sufrir un deterioro importante. Un personaje exhausto se mueve a la mitad de su velocidad y sufre un penalizador -6 tanto en la Fuerza como en la Destreza. Tras 1 hora de descanso completo, el personaje exhausto pasará a estar fatigado. Un personaje fatigado pasa a estar exhausto cuando hace algo más que normalmente produce fatiga.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'exhausto';
