update conditions set description = $c$Afectado por un intento de expulsión de muertos vivientes. Los muertos vivientes expulsados huirán durante 10 asaltos (1 minuto completo) lo más rápido que puedan y con todos los medios de que dispongan. Cuando no puedan huir, quedarán aterrados.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'expulsado';
