update conditions set description = $c$Personaje que ha acumulado un daño atenuado exactamente igual a sus puntos de golpe actuales. Un personaje grogui puede realizar una única acción de movimiento o acción estándar cada salto (pero no ambas, ni tampoco acciones de asalto completo).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'grogui';
insert into conditions (name, name_en, description, source)
select $c$Grogui$c$, $c$$c$, $c$Personaje que ha acumulado un daño atenuado exactamente igual a sus puntos de golpe actuales. Un personaje grogui puede realizar una única acción de movimiento o acción estándar cada salto (pero no ambas, ni tampoco acciones de asalto completo).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'grogui');
update conditions set description = $c$Situación en la que se encuentra quien tenga exactamente 0 puntos de golpe, o con puntos negativos pero estable y consciente. Un personaje incapacitado puede llevar a cabo una única acción de movimiento o acción estándar cada asalto (pero no ambas, ni tampoco acciones de asalto completo). Se mueve a la mitad de su velocidad, y las acciones de movimiento no le producen mayores heridas, pero realizar cualquier acción estándar (o alguna otra acción que el DM considere extenuante, incluyendo algunas acciones gratuitas como lanzar un conjuro apresurado) le inflige 1 punto de daño después de terminar la acción. Salvo que la acción aumente los puntos de golpe del personaje incapacitado, tras ello se encontrará en puntos de golpe negativos y moribundo.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'incapacitado';
insert into conditions (name, name_en, description, source)
select $c$Incapacitado$c$, $c$$c$, $c$Situación en la que se encuentra quien tenga exactamente 0 puntos de golpe, o con puntos negativos pero estable y consciente. Un personaje incapacitado puede llevar a cabo una única acción de movimiento o acción estándar cada asalto (pero no ambas, ni tampoco acciones de asalto completo). Se mueve a la mitad de su velocidad, y las acciones de movimiento no le producen mayores heridas, pero realizar cualquier acción estándar (o alguna otra acción que el DM considere extenuante, incluyendo algunas acciones gratuitas como lanzar un conjuro apresurado) le inflige 1 punto de daño después de terminar la acción. Salvo que la acción aumente los puntos de golpe del personaje incapacitado, tras ello se encontrará en puntos de golpe negativos y moribundo.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'incapacitado');
update conditions set description = $c$Sin sentido e indefenso. La inconsciencia puede deberse a tener entre -1 y-9 puntos de golpe actuales o a que el daño no letal acumulado por el personaje exceda sus puntos de golpe actuales. Un personaje inconsciente como resultado de tener entre -1 y -9 puntos de golpe que esté estable tiene un 10% de posibilidades cada hora de vol-· ver a estar consciente. Un personaje que esté inconsciente porque ha sufrido un daño no letal superior a sus puntos de golpe actuales tiene un 10 de posibilidades cada minuto de despertarse y estar grogui.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'inconsciente';
insert into conditions (name, name_en, description, source)
select $c$Inconsciente$c$, $c$$c$, $c$Sin sentido e indefenso. La inconsciencia puede deberse a tener entre -1 y-9 puntos de golpe actuales o a que el daño no letal acumulado por el personaje exceda sus puntos de golpe actuales. Un personaje inconsciente como resultado de tener entre -1 y -9 puntos de golpe que esté estable tiene un 10% de posibilidades cada hora de vol-· ver a estar consciente. Un personaje que esté inconsciente porque ha sufrido un daño no letal superior a sus puntos de golpe actuales tiene un 10 de posibilidades cada minuto de despertarse y estar grogui.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'inconsciente');
update conditions set description = $c$El personaje está paralizado, atado, inmovilizado, dormido, inconsciente o de algún otro modo a completa merced de su oponente. Se considera que un objetivo indefenso tiene una Destreza de 0 (modificador -5), y los ataques cuerpo a cuerpo contra él obtienen un bonificador +4. Un atacante puede dar un golpe de gracia a una víctima indefensa.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'indefenso';
insert into conditions (name, name_en, description, source)
select $c$Indefenso$c$, $c$$c$, $c$El personaje está paralizado, atado, inmovilizado, dormido, inconsciente o de algún otro modo a completa merced de su oponente. Se considera que un objetivo indefenso tiene una Destreza de 0 (modificador -5), y los ataques cuerpo a cuerpo contra él obtienen un bonificador +4. Un atacante puede dar un golpe de gracia a una víctima indefensa.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'indefenso');
update conditions set description = $c$Ligeramente enfermo. Un personaje indispuesto sufre un penalizador -2 en la tiradas de taque, tiradas de daño con arma, tiros de salvación y en las pruebas de habilidades y características.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'indispuesto';
insert into conditions (name, name_en, description, source)
select $c$Indispuesto$c$, $c$$c$, $c$Ligeramente enfermo. Un personaje indispuesto sufre un penalizador -2 en la tiradas de taque, tiradas de daño con arma, tiros de salvación y en las pruebas de habilidades y características.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'indispuesto');
update conditions set description = $c$Imposible de detectar visualmente. Las criaturas invisibles obtienen un bonificador +2 en las tiradas de ataque y anulan el bonificador de Destreza a la CA de sus oponentes (la invisibilidad no tiene efecto contra las criaturas cegadas o que carecen de vista por cualquier otro motivo). La localización de una criatura invisible no puede ser determinada por medios visua les. Tiene ocultación total; incluso aunque un atacante adivine de manera co rrecta el lugar donde se encuentra la criatura invisible, seguirá teniendo un 50% de posibilidades de fallar en combate. Una criatura invisible obtiene un bonificador +40 a las pruebas de Esconderse si permanece inmóvil, y de +20 si se mueve. Localizar la casilla que ocupa una criatura invisible requiere una prueba de Avistar (CD 40 si la criatura está inmóvil, o CD 20 si la criatura se movió durante su último turno), modificada por los factores apropiados (como un penalizador de armadura o un penalizador por movimiento).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'invisible';
insert into conditions (name, name_en, description, source)
select $c$Invisible$c$, $c$$c$, $c$Imposible de detectar visualmente. Las criaturas invisibles obtienen un bonificador +2 en las tiradas de ataque y anulan el bonificador de Destreza a la CA de sus oponentes (la invisibilidad no tiene efecto contra las criaturas cegadas o que carecen de vista por cualquier otro motivo). La localización de una criatura invisible no puede ser determinada por medios visua les. Tiene ocultación total; incluso aunque un atacante adivine de manera co rrecta el lugar donde se encuentra la criatura invisible, seguirá teniendo un 50% de posibilidades de fallar en combate. Una criatura invisible obtiene un bonificador +40 a las pruebas de Esconderse si permanece inmóvil, y de +20 si se mueve. Localizar la casilla que ocupa una criatura invisible requiere una prueba de Avistar (CD 40 si la criatura está inmóvil, o CD 20 si la criatura se movió durante su último turno), modificada por los factores apropiados (como un penalizador de armadura o un penalizador por movimiento).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'invisible');
update conditions set description = $c$Inconsciente y prácticamente muerto. Un personaje moribundo tendrá entre-1 y -9 puntos de golpe actuales y no podrá llevar a cabo acción alguna. Cada asalto debe tirar d% para ver si se estabiliza. Tiene un 10% de posibilidades de quedar estable, y si no lo consigue perderá 1 punto de golpe. Si un personaje moribundo alcanza los -- 10 puntos de golpe, habrá muerto.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'moribundo';
insert into conditions (name, name_en, description, source)
select $c$Moribundo$c$, $c$$c$, $c$Inconsciente y prácticamente muerto. Un personaje moribundo tendrá entre-1 y -9 puntos de golpe actuales y no podrá llevar a cabo acción alguna. Cada asalto debe tirar d% para ver si se estabiliza. Tiene un 10% de posibilidades de quedar estable, y si no lo consigue perderá 1 punto de golpe. Si un personaje moribundo alcanza los -- 10 puntos de golpe, habrá muerto.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'moribundo');
update conditions set description = $c$Un personaje muere cuando sus puntos de golpe llegan a -10 o una cifra inferior, o cuando su Constitución queda reducida a 0. Además, existen ciertos conjuros o efectos (como fallar un tiro de salvación de Fortaleza al sufrir daño masivo) que también pueden matarlo en el acto. La muerte hace que el alma del personaje abandone su cuerpo y viaje hasta un plano Exterior. Los personajes muertos no se benefician de la curación (ni normal ni mágica), pero pueden ser devueltos a la vida por medio de la magia. El cadáver se pudrirá en su totalidad si no se ponen medios para conservarlo mágicamente, pero la magia que devuelva la vida al personaje hará que se recupere hasta estar en plena forma, o que vuelva al estado en que estuviera antes de morir (dependiendo del conjuro u objeto utilizado).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'muerto';
insert into conditions (name, name_en, description, source)
select $c$Muerto$c$, $c$$c$, $c$Un personaje muere cuando sus puntos de golpe llegan a -10 o una cifra inferior, o cuando su Constitución queda reducida a 0. Además, existen ciertos conjuros o efectos (como fallar un tiro de salvación de Fortaleza al sufrir daño masivo) que también pueden matarlo en el acto. La muerte hace que el alma del personaje abandone su cuerpo y viaje hasta un plano Exterior. Los personajes muertos no se benefician de la curación (ni normal ni mágica), pero pueden ser devueltos a la vida por medio de la magia. El cadáver se pudrirá en su totalidad si no se ponen medios para conservarlo mágicamente, pero la magia que devuelva la vida al personaje hará que se recupere hasta estar en plena forma, o que vuelva al estado en que estuviera antes de morir (dependiendo del conjuro u objeto utilizado).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'muerto');
update conditions set description = $c$(también: "mareado") víctima de náuseas y malestar en el vientre. Las criaturas nauseadas no pueden atacar, lanzar conjuros, concentrarse en sus sortilegios ni hacer cualquier otra cosa que requiera su atención. La única acción que el personaje podrá llevar a cabo será una única acción de movimiento por turno, además de acciones gratuítas (salvo lanzar conjuros aprestirados).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'nauseado';
insert into conditions (name, name_en, description, source)
select $c$Nauseado$c$, $c$$c$, $c$(también: "mareado") víctima de náuseas y malestar en el vientre. Las criaturas nauseadas no pueden atacar, lanzar conjuros, concentrarse en sus sortilegios ni hacer cualquier otra cosa que requiera su atención. La única acción que el personaje podrá llevar a cabo será una única acción de movimiento por turno, además de acciones gratuítas (salvo lanzar conjuros aprestirados).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'nauseado');
update conditions set description = $c$Incapaz de moverse o actuar físicamente, como por el conjuro de inmovilizar persona. Los personajes paralizados pasan a tener una puntuación efectiva de 0 tanto en Fuerza como en Destreza y se consideran indefensos, aunque pueden realizar acciones puramente mentales. Una criatura alada que estuviese volando en el momento en que quede paralizada no puede batir sus alas, y caerá. Un nadador paralizado no puede nadar, y se hundirá. Una criatura puede moverse a través del espacio ocupado por una criatura paralizada, sea o no su aliada; no obstante, cada casilla ocupada por una criatura paraliza cuenta como 2 casillas.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'paralizado';
insert into conditions (name, name_en, description, source)
select $c$Paralizado$c$, $c$$c$, $c$Incapaz de moverse o actuar físicamente, como por el conjuro de inmovilizar persona. Los personajes paralizados pasan a tener una puntuación efectiva de 0 tanto en Fuerza como en Destreza y se consideran indefensos, aunque pueden realizar acciones puramente mentales. Una criatura alada que estuviese volando en el momento en que quede paralizada no puede batir sus alas, y caerá. Un nadador paralizado no puede nadar, y se hundirá. Una criatura puede moverse a través del espacio ocupado por una criatura paralizada, sea o no su aliada; no obstante, cada casilla ocupada por una criatura paraliza cuenta como 2 casillas.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'paralizado');
update conditions set description = $c$Convertido en piedra. Los personajes petrificados son considerados inconscientes. Si un personaje petrificado se rompe o agrieta, pero las piezas rotas vuelven a unirse al cuerpo antes de que vuelva a la carne, no sufre daño alguno. En los demás casos, el DM debe asignar una pérdida permanente de puntos de golpe y/o alguna forma de debilitamiento.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'petrificado';
insert into conditions (name, name_en, description, source)
select $c$Petrificado$c$, $c$$c$, $c$Convertido en piedra. Los personajes petrificados son considerados inconscientes. Si un personaje petrificado se rompe o agrieta, pero las piezas rotas vuelven a unirse al cuerpo antes de que vuelva a la carne, no sufre daño alguno. En los demás casos, el DM debe asignar una pérdida permanente de puntos de golpe y/o alguna forma de debilitamiento.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'petrificado');
update conditions set description = $c$Tirado en el suelo. Un atacante que esté tumbado sufrirá un penalizador -4 en las tiradas de ataque cuerpo a cuerpo y no podrá utilizar armas de ataque a distancia (a excepción de una ballesta). Un defensor tumbado obtiene un bonificador +4 a la CA contra ataques a distancia, pero sufre un penalizador - 4 a la CA contra ataques cuerpo a cuerpo.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'tumbado';
insert into conditions (name, name_en, description, source)
select $c$Tumbado$c$, $c$$c$, $c$Tirado en el suelo. Un atacante que esté tumbado sufrirá un penalizador -4 en las tiradas de ataque cuerpo a cuerpo y no podrá utilizar armas de ataque a distancia (a excepción de una ballesta). Un defensor tumbado obtiene un bonificador +4 a la CA contra ataques a distancia, pero sufre un penalizador - 4 a la CA contra ataques cuerpo a cuerpo.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from conditions where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'tumbado');

-- ---------------------------- DOTES ----------------------------

update feats set kind = $c$General$c$, benefit = $c$Puedes lanzar cualquier conjuro que tenga un componente material que cueste 1 po o menos sin precisar ese componente, aunque lanzar el conjuro sigue provocando un ataque de oportunidad de forma normal. Si el conjuro requiere un componente material que cueste más de 1 po, debes disponer de él para lanzar el conjuro, de la manera normal.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'abstencion de materiales';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Abstencion de materiales$c$, $c$$c$, $c$General$c$, $c$$c$, $c$Puedes lanzar cualquier conjuro que tenga un componente material que cueste 1 po o menos sin precisar ese componente, aunque lanzar el conjuro sigue provocando un ataque de oportunidad de forma normal. Si el conjuro requiere un componente material que cueste más de 1 po, debes disponer de él para lanzar el conjuro, de la manera normal.$c$, $c$$c$, $c$$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'abstencion de materiales');
