update feats set kind = $c$General$c$, benefit = $c$Obtienes un bonificador +4 a las siguientes pruebas y salvaciones: pruebas de Nadar realizadas para resistir daño no letal (ver pág. 78), pruebas de Constitución realizadas para seguir corriendo (pág. 144), pruebas de Constitución para evitar daño no letal debido a una marcha forzada (pág. 164), pruebas de Constitución para aguantar la respiración (pag. 78), pruebas de Constitución para evitar daño no letal debido a la sed y la inanición (ver la Guía del Dungeon Master), salvaciones de Fortaleza para evitar daño no letal de entornos fríos o cálidos (ver la Guía del Dungeon Master), y salvaciones de Fortaleza para resistir daño por asfixia (ver la Guía del Dungeon Master). Además, puedes dormir con armadura ligera o intermedia sin quedar fatigado.$c$, normal = $c$Un personaje sin esta dote que duerma con una armadura intermedia o pesada está fatigado de manera automática durante el siguiente día.$c$, special = $c$Un explorar obtiene automáticamente Aguante como dote adicional a 3.6 nivel (ver la pág. 39), por lo que no necesita elegirla.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'aguante';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Aguante$c$, $c$$c$, $c$General$c$, $c$$c$, $c$Obtienes un bonificador +4 a las siguientes pruebas y salvaciones: pruebas de Nadar realizadas para resistir daño no letal (ver pág. 78), pruebas de Constitución realizadas para seguir corriendo (pág. 144), pruebas de Constitución para evitar daño no letal debido a una marcha forzada (pág. 164), pruebas de Constitución para aguantar la respiración (pag. 78), pruebas de Constitución para evitar daño no letal debido a la sed y la inanición (ver la Guía del Dungeon Master), salvaciones de Fortaleza para evitar daño no letal de entornos fríos o cálidos (ver la Guía del Dungeon Master), y salvaciones de Fortaleza para resistir daño por asfixia (ver la Guía del Dungeon Master). Además, puedes dormir con armadura ligera o intermedia sin quedar fatigado.$c$, $c$Un personaje sin esta dote que duerma con una armadura intermedia o pesada está fatigado de manera automática durante el siguiente día.$c$, $c$Un explorar obtiene automáticamente Aguante como dote adicional a 3.6 nivel (ver la pág. 39), por lo que no necesita elegirla.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'aguante');
update feats set kind = $c$General$c$, benefit = $c$Obtienes un +2 en las pruebas de Avistar y Escuchar.$c$, special = $c$El amo de un familiar (consulta la barra lateral 'Familiares', pág. 44) obtendrá los beneficios de la dote Alerta siempre que tenga al familiar al alcance de la mano.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'alerta';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
