where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'alerta');
update feats set kind = $c$Metamágica$c$, benefit = $c$Puedes alterar un conjuro con un alcance corto, intermedio o largo para aumentar ese alcance hasta el doble. Un conjuro con un alcance corto tendrá ahora un alcance de 50' + 5'/nivel, mientras que uno de alcance intermedio llegará a los 200' + 20'/nivel y uno de largo alcance llegará hasta los 800' + 80'/nivel. Un sortilegio ampliado ocupa un espacio de conjuro un nivel superior al de su nivel real.

Los conjuros que no tengan su alcance definido por una distancia, así como los conjuros que tengan un alcance diferente a corto, intermedio o largo, no podrán ver ampliado su alcance.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'ampliar conjuro';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Ampliar conjuro$c$, $c$$c$, $c$Metamágica$c$, $c$$c$, $c$Puedes alterar un conjuro con un alcance corto, intermedio o largo para aumentar ese alcance hasta el doble. Un conjuro con un alcance corto tendrá ahora un alcance de 50' + 5'/nivel, mientras que uno de alcance intermedio llegará a los 200' + 20'/nivel y uno de largo alcance llegará hasta los 800' + 80'/nivel. Un sortilegio ampliado ocupa un espacio de conjuro un nivel superior al de su nivel real.

Los conjuros que no tengan su alcance definido por una distancia, así como los conjuros que tengan un alcance diferente a corto, intermedio o largo, no podrán ver ampliado su alcance.$c$, $c$$c$, $c$$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'ampliar conjuro');
