select $c$Aplicado$c$, $c$$c$, $c$General$c$, $c$$c$, $c$Obtienes un bonificador +2 en todas las pruebas de Descifrar escritura y Tasación.$c$, $c$$c$, $c$$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'aplicado');
update feats set kind = $c$Metamágica$c$, benefit = $c$Lanzar un conjuro apresurado se considera una acción gratuita; por tanto, podrás llevar a cabo otra acción (incluido ejecutar otro sortilegio) en el mismo asalto en que lances un conjuro apresurado. Sólo puedes ejecutar un sortilegio apresurado por asalto, y no podrás apresurar un conjuro cuyo tiempo de lanzamiento sea superior a una acción de asalto completo. Los sortilegios apresurados ocupan un espacio de conjuro cuatro niveles superior al de su nivel real. Lanzar un conjuro apresurado no provoca un ataque de oportunidad.$c$, special = $c$Esta dote no puede aplicarse a ningún conjuro lanzado espontáneamente (incluidos conjuros de hechicero, conjuros de bardo y conjuros de clérigo o druida lanzados espontáneamente), ya que aplicar una dote metamágica a un conjuro lanzado de forma espontánea aumenta automáticamente su tiempo de lanzamiento a una acción de asalto completo.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'apresurar conjuro';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Apresurar conjuro$c$, $c$$c$, $c$Metamágica$c$, $c$$c$, $c$Lanzar un conjuro apresurado se considera una acción gratuita; por tanto, podrás llevar a cabo otra acción (incluido ejecutar otro sortilegio) en el mismo asalto en que lances un conjuro apresurado. Sólo puedes ejecutar un sortilegio apresurado por asalto, y no podrás apresurar un conjuro cuyo tiempo de lanzamiento sea superior a una acción de asalto completo. Los sortilegios apresurados ocupan un espacio de conjuro cuatro niveles superior al de su nivel real. Lanzar un conjuro apresurado no provoca un ataque de oportunidad.$c$, $c$$c$, $c$Esta dote no puede aplicarse a ningún conjuro lanzado espontáneamente (incluidos conjuros de hechicero, conjuros de bardo y conjuros de clérigo o druida lanzados espontáneamente), ya que aplicar una dote metamágica a un conjuro lanzado de forma espontánea aumenta automáticamente su tiempo de lanzamiento a una acción de asalto completo.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'apresurar conjuro');
update feats set kind = $c$General$c$, prerequisite = $c$Ataque poderoso, Fue 13.$c$, benefit = $c$Cuando intentas arrollar a un oponente, el objetivo no puede decidir evitarte. Además, recibes un bonificador +4 a la prueba de Fuerza para derribar a tu oponente.$c$, normal = $c$Sin esta dote, el objetivo de un intento de arrollar puede elegir evitarte o bloquearte.$c$, special = $c$Un guerrero puede elegir Arrollar mejorado como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'arrollar mejorado';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Arrollar mejorado$c$, $c$$c$, $c$General$c$, $c$Ataque poderoso, Fue 13.$c$, $c$Cuando intentas arrollar a un oponente, el objetivo no puede decidir evitarte. Además, recibes un bonificador +4 a la prueba de Fuerza para derribar a tu oponente.$c$, $c$Sin esta dote, el objetivo de un intento de arrollar puede elegir evitarte o bloquearte.$c$, $c$Un guerrero puede elegir Arrollar mejorado como una de sus dotes adicionales (ver la pág. 41).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'arrollar mejorado');
update feats set kind = $c$General$c$, prerequisite = $c$Combatir desde una montura, Montar 1 rango.$c$, benefit = $c$Cuando vayas sobre una montura y uses la acción de carga, podrás mover y atacar como si se tratase de una carga estándar y volver a moverte a continuación (siguiendo la línea recta de la carga). Tu movimiento total durante ese asalto no podrá exceder el doble de la velocidad de tu montura. Además, ni tu montura ni tú os veréis expuestos a un ataque de oportunidad por parte del oponente al que ataques.$c$, special = $c$Un guerrero puede elegir Ataque al galope como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'ataque al galope';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Ataque al galope$c$, $c$$c$, $c$General$c$, $c$Combatir desde una montura, Montar 1 rango.$c$, $c$Cuando vayas sobre una montura y uses la acción de carga, podrás mover y atacar como si se tratase de una carga estándar y volver a moverte a continuación (siguiendo la línea recta de la carga). Tu movimiento total durante ese asalto no podrá exceder el doble de la velocidad de tu montura. Además, ni tu montura ni tú os veréis expuestos a un ataque de oportunidad por parte del oponente al que ataques.$c$, $c$$c$, $c$Un guerrero puede elegir Ataque al galope como una de sus dotes adicionales (ver la pág. 41).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'ataque al galope');
update feats set kind = $c$General$c$, prerequisite = $c$ataque base +4, Ataque elástico, Des 13, Esquiva, Int 13, Movilidad, Pericia en combate.$c$, benefit = $c$Al optar por la acción de ataque completo, puedes renunciar a tus ataques normales y, en su lugar, asestar un golpe de cuerpo a cuerpo con tu ataque base completo a todos los oponentes dentro de tu alcance. Cuando usas la dote Ataque de torbellino pierdes cualquier ataque adicional proporcionado por otras dotes o aptitudes (como la dote Hendedura o el conjuro acelerar).$c$, special = $c$Un guerrero puede elegir Ataque de torbellino como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'ataque de torbellino';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Ataque de torbellino$c$, $c$$c$, $c$General$c$, $c$ataque base +4, Ataque elástico, Des 13, Esquiva, Int 13, Movilidad, Pericia en combate.$c$, $c$Al optar por la acción de ataque completo, puedes renunciar a tus ataques normales y, en su lugar, asestar un golpe de cuerpo a cuerpo con tu ataque base completo a todos los oponentes dentro de tu alcance. Cuando usas la dote Ataque de torbellino pierdes cualquier ataque adicional proporcionado por otras dotes o aptitudes (como la dote Hendedura o el conjuro acelerar).$c$, $c$$c$, $c$Un guerrero puede elegir Ataque de torbellino como una de sus dotes adicionales (ver la pág. 41).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'ataque de torbellino');
update feats set kind = $c$General$c$, prerequisite = $c$ataque base +4 o superior, Des 13, Esquiva, Movilidad.$c$, benefit = $c$Al usar la acción de ataque con un arma de cuerpo a cuerpo, puedes moverte tanto antes como después del ataque, siempre y cuando la distancia total a mover no sea mayor que tu velocidad. Al desplazarte de este mo-

do no te verás expuesto a un ataque de oportunidad por parte del defensor, aunque eso puede provocar ataques de oportunidad de otras criaturas, cuando sea apropiado. No podrás usar esta dote si llevas puesta armadura pesada. Debes moverte al menos 5' tanto antes como después de realizar tu ataque para poder utilizar los beneficios de un Ataque elástico.$c$, special = $c$Un guerrero puede elegir Ataque elástico como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'ataque elastico';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Ataque elastico$c$, $c$$c$, $c$General$c$, $c$ataque base +4 o superior, Des 13, Esquiva, Movilidad.$c$, $c$Al usar la acción de ataque con un arma de cuerpo a cuerpo, puedes moverte tanto antes como después del ataque, siempre y cuando la distancia total a mover no sea mayor que tu velocidad. Al desplazarte de este mo-

do no te verás expuesto a un ataque de oportunidad por parte del defensor, aunque eso puede provocar ataques de oportunidad de otras criaturas, cuando sea apropiado. No podrás usar esta dote si llevas puesta armadura pesada. Debes moverte al menos 5' tanto antes como después de realizar tu ataque para poder utilizar los beneficios de un Ataque elástico.$c$, $c$$c$, $c$Un guerrero puede elegir Ataque elástico como una de sus dotes adicionales (ver la pág. 41).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'ataque elastico');
update feats set kind = $c$General$c$, prerequisite = $c$Fue 13.$c$, benefit = $c$En tu acción, antes de realizar las tiradas de ataque del asalto en curso, puedes elegir restar una cantidad a todas tus tiradas de ataque cuerpo a cuerpo y añadir esa misma cantidad a todas las tiradas de daño en cuerpo a cuerpo. El número elegido no puede superar tu ataque base. La penalización a los ataques y los bonificadores al daño se aplicarán hasta tu siguiente acción.$c$, special = $c$Si atacas con un arma a dos manos, o con un arma a una mano esgrimida con ambas manos, suma al daño el doble de la cantidad restada a las tiradas de ataque. No puedes sumar el bonificador al daño por Ataque poderoso al daño infligido con un arma ligera (salvo los impactos sin arma o los ataques con armas naturales), aunque el penalizador a las tiradas de ataque seguirá aplicándose. Ten en cuenta que normalmente un arma doble se considera como un arma a una mano y un arma ligera; no obstante, puedes elegir utilizarla como un arma a dos manos, utilizando sólo un extremo en cada asalto).

Un guerrero puede elegir Ataque poderoso como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'ataque poderoso';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Ataque poderoso$c$, $c$$c$, $c$General$c$, $c$Fue 13.$c$, $c$En tu acción, antes de realizar las tiradas de ataque del asalto en curso, puedes elegir restar una cantidad a todas tus tiradas de ataque cuerpo a cuerpo y añadir esa misma cantidad a todas las tiradas de daño en cuerpo a cuerpo. El número elegido no puede superar tu ataque base. La penalización a los ataques y los bonificadores al daño se aplicarán hasta tu siguiente acción.$c$, $c$$c$, $c$Si atacas con un arma a dos manos, o con un arma a una mano esgrimida con ambas manos, suma al daño el doble de la cantidad restada a las tiradas de ataque. No puedes sumar el bonificador al daño por Ataque poderoso al daño infligido con un arma ligera (salvo los impactos sin arma o los ataques con armas naturales), aunque el penalizador a las tiradas de ataque seguirá aplicándose. Ten en cuenta que normalmente un arma doble se considera como un arma a una mano y un arma ligera; no obstante, puedes elegir utilizarla como un arma a dos manos, utilizando sólo un extremo en cada asalto).

Un guerrero puede elegir Ataque poderoso como una de sus dotes adicionales (ver la pág. 41).$c$, $c$Manual del Jugador 3.5$c$
