update feats set kind = $c$General$c$, prerequisite = $c$Des 15.$c$, benefit = $c$Tus penalizaciones por combatir con dos armas se reducen. El penalizador de tu mano hábil se reduce en 2, y el de tu mano torpe en 6.$c$, normal = $c$Consulta 'Combatir con dos armas', en la pág. 155, y la tabla 8-10: penalizadores por combatir con dos armas, en la pág. 160.$c$, special = $c$Se considera que un explorador de 2.º nivel que haya elegido el estilo de combate con dos armas tiene la dote Combate con dos armas, incluso aunque no tenga los prerrequisitos. No obstante, sólo recibe los beneficios de la dote cuando lleva armadura ligera o no lleva armadura (ver la pág. 48). Un guerrero puede elegir Combate con dos armas como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'combate con dos armas';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Combate con dos armas$c$, $c$$c$, $c$General$c$, $c$Des 15.$c$, $c$Tus penalizaciones por combatir con dos armas se reducen. El penalizador de tu mano hábil se reduce en 2, y el de tu mano torpe en 6.$c$, $c$Consulta 'Combatir con dos armas', en la pág. 155, y la tabla 8-10: penalizadores por combatir con dos armas, en la pág. 160.$c$, $c$Se considera que un explorador de 2.º nivel que haya elegido el estilo de combate con dos armas tiene la dote Combate con dos armas, incluso aunque no tenga los prerrequisitos. No obstante, sólo recibe los beneficios de la dote cuando lleva armadura ligera o no lleva armadura (ver la pág. 48). Un guerrero puede elegir Combate con dos armas como una de sus dotes adicionales (ver la pág. 41).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'combate con dos armas');
update feats set kind = $c$General$c$, prerequisite = $c$Combate con dos armas, Combate con dos armas mejorado, Des 19, ataque base +11.$c$, benefit = $c$Obtienes un tercer ataque con tu mano torpe, aunque con un penalizador -10.$c$, special = $c$Un guerrero puede elegir Combate con dos armas mayor como una de sus dotes adicionales (ver la pág. 41).

Un explorador de 11.º nivel que haya elegido el estilo de combate con dos armas obtiene Combate con dos armas mayor, incluso aunque no tenga los prerrequisitos para ello. No obstante, sólo recibe los beneficios de la dote cuando lleva armadura ligera o no lleve armadura (ver la pág. 39).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'combate con dos armas mayor';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Combate con dos armas mayor$c$, $c$$c$, $c$General$c$, $c$Combate con dos armas, Combate con dos armas mejorado, Des 19, ataque base +11.$c$, $c$Obtienes un tercer ataque con tu mano torpe, aunque con un penalizador -10.$c$, $c$$c$, $c$Un guerrero puede elegir Combate con dos armas mayor como una de sus dotes adicionales (ver la pág. 41).

Un explorador de 11.º nivel que haya elegido el estilo de combate con dos armas obtiene Combate con dos armas mayor, incluso aunque no tenga los prerrequisitos para ello. No obstante, sólo recibe los beneficios de la dote cuando lleva armadura ligera o no lleve armadura (ver la pág. 39).$c$, $c$Manual del Jugador 3.5$c$
