update feats set kind = $c$General$c$, prerequisite = $c$ataque base +9, Des 17, Combate con dos armas.$c$, benefit = $c$Además del ataque adicional que normalmente puede realizarse con un arma sujeta con la mano torpe, dispondrás de un segundo ataque con esa misma mano, aunque con un penalizador -5 (consulta la tabla 8-10, en la pág. 160).$c$, normal = $c$Sin esta dote sólo podrás llevar a cabo un ataque adicional con el arma que tengas en la mano torpe.$c$, special = $c$Un guerrero puede elegir Combate con dos armas mayor como una de sus dotes adicionales (ver la pág. 41).

Un explorador de 6.º nivel que haya elegido el estilo de combate con dos armas obtiene Combate con dos armas mejorado, incluso aunque no tenga los prerrequisitos para ello. No obstante, sólo recibe los beneficios de la dote cuando lleva armadura ligera o no lleva armadura (ver la pág. 39).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'combate con dos armas mejorado';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Combate con dos armas mejorado$c$, $c$$c$, $c$General$c$, $c$ataque base +9, Des 17, Combate con dos armas.$c$, $c$Además del ataque adicional que normalmente puede realizarse con un arma sujeta con la mano torpe, dispondrás de un segundo ataque con esa misma mano, aunque con un penalizador -5 (consulta la tabla 8-10, en la pág. 160).$c$, $c$Sin esta dote sólo podrás llevar a cabo un ataque adicional con el arma que tengas en la mano torpe.$c$, $c$Un guerrero puede elegir Combate con dos armas mayor como una de sus dotes adicionales (ver la pág. 41).

Un explorador de 6.º nivel que haya elegido el estilo de combate con dos armas obtiene Combate con dos armas mejorado, incluso aunque no tenga los prerrequisitos para ello. No obstante, sólo recibe los beneficios de la dote cuando lleva armadura ligera o no lleva armadura (ver la pág. 39).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'combate con dos armas mejorado');
update feats set kind = $c$General$c$, prerequisite = $c$Montar 1 rango.$c$, benefit = $c$Una vez por asalto, podrás realizar una prueba de Montar (como reacción) para anular un golpe recibido por tu montura en combate. El golpe quedará anulado siempre y cuando tu prueba de Montar sea superior a la tirada de ataque (básicamente, la prueba de Montar se convertirá en la CA de la montura en caso de ser superior a la CA normal de ésta).$c$, special = $c$Un guerrero puede elegir Combatir desde una montura como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'combatir desde una montura';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Combatir desde una montura$c$, $c$$c$, $c$General$c$, $c$Montar 1 rango.$c$, $c$Una vez por asalto, podrás realizar una prueba de Montar (como reacción) para anular un golpe recibido por tu montura en combate. El golpe quedará anulado siempre y cuando tu prueba de Montar sea superior a la tirada de ataque (básicamente, la prueba de Montar se convertirá en la CA de la montura en caso de ser superior a la CA normal de ésta).$c$, $c$$c$, $c$Un guerrero puede elegir Combatir desde una montura como una de sus dotes adicionales (ver la pág. 41).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'combatir desde una montura');
update feats set kind = $c$General$c$, prerequisite = $c$ataque base +1 (además de Fue 13 para la espada bastarda o el hacha de guerra enana).$c$, benefit = $c$Haces tus tiradas de ataque con este arma de la manera normal.$c$, normal = $c$Un personaje que use un arma sin ser competente con ella sufrirá un penalizador -4 en sus tiradas de ataque.$c$, special = $c$Puedes adquirir esta dote varias veces. Cada vez que lo hagas, el beneficio se aplicará a un arma exótica diferente. La competencia con la espada bastarda o el hacha de guerra enana tienen un prerrequisito adicional de Fue 13.

Un guerrero puede elegir Competencia con arma exótica como una de sus dotes adicionales (ver la pág. 41).

![](_page_93_Picture_4.jpeg)$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'competencia con arma exotica';
