update feats set kind = $c$General$c$, benefit = $c$Puedes usar escudo y sufrir solamente las penalizaciones normales (consulta la tabla 7-6: armadura y escudos, pág. 123).$c$, normal = $c$Los personajes que utilizan un escudo en cuyo uso no son competentes sufren el correspondiente penalizador de armadura en las tiradas de ataque y en todas las pruebas de habilidad que impliquen movimiento, incluidas las de Montar.$c$, special = $c$Los bárbaros, bardos, clérigos, druidas, exploradores, guerreros y paladines obtienen esta dote de forma gratuita, por lo que no necesitan elegirla.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'competencia con escudo';
