update feats set kind = $c$Metamágica$c$, benefit = $c$Un conjuro silencioso puede ser ejecutado sin componentes verbales. Los conjuros que carezcan de componente verbal no resultan afectados por esta dote. Los sortilegios silenciosos ocupan un espacio de conjuro un nivel superior al de su nivel real.$c$, special = $c$Los conjuros de bardo no pueden recibir las ventajas de esta dote metamágica.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'conjurar en silencio';
