update feats set kind = $c$General$c$, benefit = $c$Al realizar un contraconjuro, puedes utilizar cualquier sortilegio de la misma escuela, siempre que sea uno o más niveles superior al conjuro objetivo.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'contraconjuro mejorado';
