update feats set kind = $c$General$c$, benefit = $c$Al correr, te mueves 5 veces más rápido de lo normal en lugar de 4 (si no llevas armadura o llevas armadura ligera y no transportas más de una carga ligera) o a 4 veces tu velocidad (si llevas armadura intermedia o pesada o transportas una carga mediana o pesada). Si realizas un salto después de una carrera inicial (consulta la descripción de la habilidad Saltar, en la pág.80), obtienes un bonificador +4 en tu prueba de Saltar. Mientras corres conservas tu bonificador de Des a la CA.$c$, normal = $c$Cuando corres te mueves a 4 veces tu velocidad (si no llevas armadura o llevas armadura ligera y no transportas más de una carga ligera)o a 3 veces tu velocidad (si llevas armadura intermedia o pesada o transportas una carga mediana o pesada), y pierdes tu bonificador de Des a la CA.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'correr';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Correr$c$, $c$$c$, $c$General$c$, $c$$c$, $c$Al correr, te mueves 5 veces más rápido de lo normal en lugar de 4 (si no llevas armadura o llevas armadura ligera y no transportas más de una carga ligera) o a 4 veces tu velocidad (si llevas armadura intermedia o pesada o transportas una carga mediana o pesada). Si realizas un salto después de una carrera inicial (consulta la descripción de la habilidad Saltar, en la pág.80), obtienes un bonificador +4 en tu prueba de Saltar. Mientras corres conservas tu bonificador de Des a la CA.$c$, $c$Cuando corres te mueves a 4 veces tu velocidad (si no llevas armadura o llevas armadura ligera y no transportas más de una carga ligera)o a 3 veces tu velocidad (si llevas armadura intermedia o pesada o transportas una carga mediana o pesada), y pierdes tu bonificador de Des a la CA.$c$, $c$$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'correr');
update feats set kind = $c$General$c$, prerequisite = $c$ataque base +8 o superior, competencia con el arma.$c$, benefit = $c$Tu rango de amenaza se duplicará cuando uses el arma elegida. Por ejemplo, una espada larga normalmente amenaza con hacer crítico obteniendo 19-20 (dos números). Si el personaje que usara la espada larga tuviera Crítico mejorado (espada larga), el rango de amenaza del arma se situaría entre 17-20 (cuatro números).$c$, special = $c$Puedes obtener esta dote varias veces, pero sus efectos no se apilarán. Cada vez que adquieras la dote, deberá aplicarse a una nueva arma.

Este efecto no se apila con ningún otro efecto que expanda el rango de amenaza de un arma

(como el conjuro afiladura). Un guerrero puede elegir Crítico mejorado como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'critico mejorado';
