update feats set kind = $c$General$c$, prerequisite = $c$Int 13, Pericia en combate.$c$, benefit = $c$No provocas ataque de oportunidad cuando intentas desarmar a un oponente, ni éste tendrá oportunidad de desarmarte a ti. Además, obtienes un bonif. +4 en la tirada de ataque enfrentada para desarmar a tu oponente.$c$, normal = $c$Consulta las reglas normales de desarme, pág. 156.$c$, special = $c$Un guerrero puede elegir Desarme mejorado como una de sus dotes adicionales (ver la pág. 41).

Un monje puede elegir Desarme mejorado como dote adicional a 6.º nivel, incluso aunque no reúna los prerrequisitos.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'desarme mejorado';
