update feats set kind = $c$General$c$, prerequisite = $c$Des 13+, Impacto sin arma mejorado.$c$, benefit = $c$Para usar esta dote debes tener libre una mano como mínimo (es decir, no estar sujetando nada con ella). Una vez por asalto, cuando en circunstancias normales serias golpeado por un arma de ataque a distancia, puedes desviar el ataque para no recibir ningún daño de él. Para poder hacerlo debes ser consciente del ataque y no estar desprevenido. Intentar desviar un arma de ataque a distancia no cuenta como acción. Las armas de ataque a distancia excepcionalmente grandes, como las rocas arrojadas por los gigantes, no pueden ser desviadas, ni tampoco los ataques a distancia generados por efectos de conjuros, como una flecha ácida de Melf.$c$, special = $c$Un monje puede elegir Desviar flechas como dote adicional a 2ª nivel, aunque no cumpla el prerrequisito de la puntuación de Destreza.

Un guerrero puede elegir Desviar flechas como una de sus dotes adi-

cionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'desviar flechas';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Desviar flechas$c$, $c$$c$, $c$General$c$, $c$Des 13+, Impacto sin arma mejorado.$c$, $c$Para usar esta dote debes tener libre una mano como mínimo (es decir, no estar sujetando nada con ella). Una vez por asalto, cuando en circunstancias normales serias golpeado por un arma de ataque a distancia, puedes desviar el ataque para no recibir ningún daño de él. Para poder hacerlo debes ser consciente del ataque y no estar desprevenido. Intentar desviar un arma de ataque a distancia no cuenta como acción. Las armas de ataque a distancia excepcionalmente grandes, como las rocas arrojadas por los gigantes, no pueden ser desviadas, ni tampoco los ataques a distancia generados por efectos de conjuros, como una flecha ácida de Melf.$c$, $c$$c$, $c$Un monje puede elegir Desviar flechas como dote adicional a 2ª nivel, aunque no cumpla el prerrequisito de la puntuación de Destreza.

Un guerrero puede elegir Desviar flechas como una de sus dotes adi-

cionales (ver la pág. 41).$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'desviar flechas');
update feats set kind = $c$General$c$, prerequisite = $c$Combatir desde una montura, Montar 1 rango.$c$, benefit = $c$La penalización que sufres por usar un arma de ataque a distancia a lomos de una montura se reduce a la mitad: -2 en lugar de -4 si tu montura está llevando a cabo un movimiento doble, y -4 en lugar de -8 si lo que hace es correr (consulta 'Combatir desde una montura', en la pag. 155).$c$, special = $c$Un guerrero puede elegir Disparar desde una montura como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'disparar desde una montura';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
