update feats set kind = $c$General$c$, prerequisite = $c$Disparo a bocajarro.$c$, benefit = $c$Cuando uses un arma de proyectil, como un arco, su alcance se incrementa en un 50% (multiplícalo por 1'5). Cuando utilices un arma arrojadiza, su alcance se duplica.$c$, special = $c$Un guerrero puede elegir Disparo a larga distancia como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'disparo a larga distancia';
