update feats set kind = $c$General$c$, prerequisite = $c$Disparo a bocajarro.$c$, benefit = $c$Puedes disparar o lanzar armas de ataque a distancia contra un oponente enzarzado en combate cuerpo a cuerpo sin sufrir el penalizador -4 normal en tu tirada de ataque (consulta Ataques a distancia contra blancos en cuerpo a cuerpo, en la pág. 140).$c$, special = $c$Un guerrero puede elegir Disparo preciso como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'disparo preciso';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Disparo preciso$c$, $c$$c$, $c$General$c$, $c$Disparo a bocajarro.$c$, $c$Puedes disparar o lanzar armas de ataque a distancia contra un oponente enzarzado en combate cuerpo a cuerpo sin sufrir el penalizador -4 normal en tu tirada de ataque (consulta Ataques a distancia contra blancos en cuerpo a cuerpo, en la pág. 140).$c$, $c$$c$, $c$Un guerrero puede elegir Disparo preciso como una de sus dotes adicionales (ver la pág. 41).$c$, $c$Manual del Jugador 3.5$c$
