update feats set kind = $c$General$c$, prerequisite = $c$ataque base +11, Des 19, Disparo a bocajarro, Disparo preciso.$c$, benefit = $c$Tus ataques a distancia ignoran el bonificador a la CA que tenga cualquier objetivo debido a cobertura (siempre que no tenga cobertura total), y la posibilidad de fallo debido a ocultación (siempre que no tenga ocultación total). La cobertura total y la ocultación total proporcionan los beneficios normales contra tus ataques a distancia. Además, cuando disparas o lanzas

armas con alcance a oponentes enzarzados en una presa, golpeas automáticamente al oponente que elijas.$c$, normal = $c$Consulta las págs. 150-152 para las reglas sobre los efectos de la cobertura y la ocultación en combate. Sin esta dote, un personaje que dispare o lance un arma a distancia a un objetivo enzarzado en una presa debe determinar aleatoriamente a cuál de los combatientes de la presa golpea.$c$, special = $c$Un guerrero puede elegir Disparo preciso mejorado como una de sus dotes adicionales (ver la pág. 41).

Se considera que un explorador de 11.º nivel que haya elegido el estilo de combate tiro con arco posee la dote Disparo preciso mejorado, incluso aunque no tenga los prerrequisitos para ella. No obstante, sus efectos sólo se aplican cuando lleva armadura ligera o no lleva armadura (ver la pág. 39).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'disparo preciso mejorado';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Disparo preciso mejorado$c$, $c$$c$, $c$General$c$, $c$ataque base +11, Des 19, Disparo a bocajarro, Disparo preciso.$c$, $c$Tus ataques a distancia ignoran el bonificador a la CA que tenga cualquier objetivo debido a cobertura (siempre que no tenga cobertura total), y la posibilidad de fallo debido a ocultación (siempre que no tenga ocultación total). La cobertura total y la ocultación total proporcionan los beneficios normales contra tus ataques a distancia. Además, cuando disparas o lanzas

armas con alcance a oponentes enzarzados en una presa, golpeas automáticamente al oponente que elijas.$c$, $c$Consulta las págs. 150-152 para las reglas sobre los efectos de la cobertura y la ocultación en combate. Sin esta dote, un personaje que dispare o lance un arma a distancia a un objetivo enzarzado en una presa debe determinar aleatoriamente a cuál de los combatientes de la presa golpea.$c$, $c$Un guerrero puede elegir Disparo preciso mejorado como una de sus dotes adicionales (ver la pág. 41).

Se considera que un explorador de 11.º nivel que haya elegido el estilo de combate tiro con arco posee la dote Disparo preciso mejorado, incluso aunque no tenga los prerrequisitos para ella. No obstante, sus efectos sólo se aplican cuando lleva armadura ligera o no lleva armadura (ver la pág. 39).$c$, $c$Manual del Jugador 3.5$c$
