update feats set kind = $c$Especial$c$, prerequisite = $c$mago de 1." nivel.$c$, benefit = $c$Cada vez que escojas esta dote, elige un número de conjuros. que ya conozcas igual a tu modificador de Inteligencia. Desde ese momento puedes preparar esos conjuros sin tener que acudir a un libro de conjuros.$c$, normal = $c$Sin esta dote debes utilizar un libro de conjuros para preparar todos tus conjuros salvo leer magia.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'maestria en conjuros';
