update feats set kind = $c$Metamágica$c$, benefit = $c$Todos los efectos numéricos y variables de un conjuro maximizado se incrementan al máximo posible. Según corresponda, un conjuro de este tipo infligirá el daño máximo, curará el máximo de puntos de golpe, afectará al máximo número posible de enemigos, etc. Por ejemplo, una bola de fuego maximizada infligirá 6 puntos de daño por nivel del lanzador (hasta 60 puntos de daño como máximo a nivel de lanzador 10.º). Los TS y las tiradas enfrentadas (como la que se hace al ejecutar un disipar magia) no resultan afectados, como tampoco lo son los conjuros que carezcan de variables aleatorias. Los sortilegios maximizados ocupan un espacio de conjuro 3 niveles superior al de su nivel real.

Un conjuro potenciado y maximizado ganará por separado los beneficios de cada dote: el resultado máximo más un 50% del resultado obtenido normalmente en los dados. Así, una bola de fuego maximizada y potenciada lanzada por un mago de 10.º nivel infligiría 60 puntos más la mitad de 10d6.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'maximizar conjuro';
insert into feats (name, name_en, kind, prerequisite, benefit, normal, special, source)
select $c$Maximizar conjuro$c$, $c$$c$, $c$Metamágica$c$, $c$$c$, $c$Todos los efectos numéricos y variables de un conjuro maximizado se incrementan al máximo posible. Según corresponda, un conjuro de este tipo infligirá el daño máximo, curará el máximo de puntos de golpe, afectará al máximo número posible de enemigos, etc. Por ejemplo, una bola de fuego maximizada infligirá 6 puntos de daño por nivel del lanzador (hasta 60 puntos de daño como máximo a nivel de lanzador 10.º). Los TS y las tiradas enfrentadas (como la que se hace al ejecutar un disipar magia) no resultan afectados, como tampoco lo son los conjuros que carezcan de variables aleatorias. Los sortilegios maximizados ocupan un espacio de conjuro 3 niveles superior al de su nivel real.

Un conjuro potenciado y maximizado ganará por separado los beneficios de cada dote: el resultado máximo más un 50% del resultado obtenido normalmente en los dados. Así, una bola de fuego maximizada y potenciada lanzada por un mago de 10.º nivel infligiría 60 puntos más la mitad de 10d6.$c$, $c$$c$, $c$$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'maximizar conjuro');
update feats set kind = $c$General$c$, prerequisite = $c$Des 13, Esquiva.$c$, benefit = $c$Obtienes un bonificador +4 de esquiva a la CA contra los ataques de oportunidad que generes al intentar moverte en el interior o al intentar salir de un área amenazada. Toda condición que te haga perder el bonificador por Destreza a la CA (caso de tenerlo) también te privará de los bonificadores de esquiva. Al contrario de lo que sucede con bonificadores de otros tipos, los de esquiva (como el concedido por esta dote y el bonificador racial que poseen los enanos para esquivar los ataques de los gigantes) pueden apilarse entre sí.$c$, special = $c$Un guerrero puede elegir Movilidad como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'movilidad';
