update feats set kind = $c$General$c$, prerequisite = $c$Int 13.$c$, benefit = $c$Cuando uses la acción de ataque o la acción de ataque completo en cuerpo a cuerpo, podrás sufrir voluntariamente un penalizador de hasta -5 en tu tirada de ataque y añadir ese mismo número (+5 o menos) como un bonificador de esquiva a tu CA. El citado número no podrá exceder tu ataque base. Los cambios a las tiradas de ataque y a la CA durarán hasta tu siguiente acción.$c$, normal = $c$Un personaje que carezca de la dote Pericia en combate podrá combatir a la defensiva cuando use la acción de ataque o la acción de ataque completo, sufriendo un penalizador -4 en los ataques a cambio de obtener un bonificador +2 de esquiva a la CA.$c$, special = $c$Un guerrero puede elegir Pericia en combate como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'pericia en combate';
