update feats set kind = $c$General$c$, prerequisite = $c$Combatir desde una montura, Montar 1 rango.$c$, benefit = $c$Cuando vayas sobre una montura e intentes arrollar a un oponente, éste no tendrá posibilidad de evitarte. Tu montura podrá lanzar un ataque de pezuña contra cualquier objetivo derribado, obteniendo el bonificador habitual +4 a las tiradas de ataque contra las víctimas que estén tumbadas (consulta 'Arrollar', en la pág. 154).$c$, special = $c$Un guerrero puede elegir Arrollar como una de sus dotes adicionales (ver la pág. 41).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'pisotear';
