select $c$Soltura mayor con una escuela de magia$c$, $c$$c$, $c$General$c$, $c$$c$, $c$Suma +1 a la CD de todos los tiros de salvación contra conjuros de la escuela de magia en que hayas elegido concentrarte. Esto bo nificador se apila con el de Soltura con una escuela de magia.$c$, $c$$c$, $c$Puedes adquirir esta dote varias veces, pero sus efectos no se apilarán. Cada vez que lo hagas, se aplicará a una nueva escuela de magia a la que ya hayas aplicado la dote Soltura con una escuela de magia.$c$, $c$Manual del Jugador 3.5$c$
where not exists (select 1 from feats where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'soltura mayor con una escuela de magia');
update feats set kind = $c$General$c$, prerequisite = $c$ataque base +1 o superior, competencia con el arma.$c$, benefit = $c$Con un arma ligera, cadena armada, estoque o látigo hechos para una criatura de tu categoría de tamaño, puedes usar tu modificador de Destreza en lugar del de Fuerza en las tiradas de ataque. Si llevas un escudo, el penalizador de armadura de éste se aplicará a tus tiradas de ataque.$c$, special = $c$Un guerrero puede elegir Sutileza con las armas como una de sus dotes adicionales (ver la pág. 41).

Las armas naturales siempre son consideradas armas ligeras.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'sutileza con las armas';
