-- -------------------------- APTITUDES --------------------------

alter table class_features alter column description type text;

update class_features set clazz = $c$Bárbaro$c$, kind = $c$Extraordinaria$c$, description = $c$La velocidad de los bárbaros es 10' superior a la de otros miembros de su raza, siempre que vayan sin armadura o con armadura ligera o intermedia, y no lleven una carga pesada. Aplica este bonificador antes de modificar la velocidad del bárbaro por causa de cualquier carga transportada o armadura que lleve. Por ejemplo, un bárbaro humano tendría una velocidad de 40 en vez de 30', siempre que vaya sin armadura o con armadura ligera. Cuando lleve una armadura intermedia o una carga mediana, su velocidad desciende a 30'. Un mediano que sea bárbaro tiene una velocidad de 30', en lugar de 20', con armadura ligera o sin armadura. Cuando lleve una armadura intermedia o transporte una carga mediana, su velocidad bajará a 20'.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'movimiento rapido' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Movimiento rápido$c$, $c$Bárbaro$c$, $c$Extraordinaria$c$, $c$La velocidad de los bárbaros es 10' superior a la de otros miembros de su raza, siempre que vayan sin armadura o con armadura ligera o intermedia, y no lleven una carga pesada. Aplica este bonificador antes de modificar la velocidad del bárbaro por causa de cualquier carga transportada o armadura que lleve. Por ejemplo, un bárbaro humano tendría una velocidad de 40 en vez de 30', siempre que vaya sin armadura o con armadura ligera. Cuando lleve una armadura intermedia o una carga mediana, su velocidad desciende a 30'. Un mediano que sea bárbaro tiene una velocidad de 30', en lugar de 20', con armadura ligera o sin armadura. Cuando lleve una armadura intermedia o transporte una carga mediana, su velocidad bajará a 20'.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'movimiento rapido' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro');
update class_features set clazz = $c$Bárbaro$c$, kind = $c$Extraordinaria$c$, description = $c$Un bárbaro puede dejarse llevar por una furia sedienta de sangre varias veces al día. Cuando está enfurecido, adquiere una fuerza y una resistencia asombrosas, pero también se vuelve temerario y disminuye su capacidad para defenderse. El bárbaro obtiene temporalmente un bonificador +4 a la Fuerza, un bonifica- dor +4 a la Constitución y un bonificador +2 de moral a los TS de Voluntad, pero también sufre un penalizador -2 a la CA La mejora de la Constitución incrementa los puntos de golpe del bárbaro en 2 por nivel, pero éstos desaparecerán al finalizar la furia, cuando la puntuación de la característica sea de nuevo la normal (a diferencia de lo que sucede con los puntos de golpe temporales, estos puntos adicionales no son los primeros en perderse al sufrir daño; consulta 'Puntos de golpe temporales', en la pág. 146). Mientras esté inmerso en su furia, un bárbaro no podrá utilizar ninguna habilidad basada en el Carisma, la Destreza o la Inteligencia (salvo Equilibrio, Escapismo, Intimidar y Montar), la habilidad de Concentración ni cualquier otra habilidad o característica que requiera paciencia o concentración; tampoco podrá lanzar conjuros o activar un objeto mágico que requiera una palabra de mando, un desencadenante de conjuro (como una varita), o finalización de conjuro (como un rollo de pergamino) para funcionar. Puede utilizar cualquier dote que posea, excepto Pericia en combate, dotes de creación de objetos y dotes metamágicas. Un ataque de furia dura una cantidad de asaltos igual a 3 + el (recién mejorado) modificador de Constitución del personaje. El bárbaro podrá poner fin a su furia voluntariamente antes de tiempo. Al finalizar el ataque de furia, el personaje estará fatigado (penalizador -2 a Fuerza, penalizador -2 a Destreza y no podrá correr ni cargar) durante el resto del encuentro (a no ser que el bárbaro haya alcanzado el nivel 17.º, momento en que ya no se aplicará la ish + + + ] 9 limitación, ver más adelante). 2000 Un bárbaro sólo puede entrar en un estado de furia una vez por encuentro. A 1.ª nivel puede utilizar su aptitud de furia una vez al día. A 4.º nivel y cada cuatro niveles adicionales, puede utilizarla una vez adicional por día (hasta un máximo de seis veces al día a nivel 20.º). Iniciar el ataque de furia no Krusk consumirá tiempo de por sí, pero el bárbaro sólo podrá hacerlo durante su acción (consulta 'Iniciativa', en la pág. 136), no como respuesta a la acción de otra persona. Si, por ejemplo, el bárbaro fuera golpeado | | TABLA 3-3: EL BARBARO | | | | | | | | | | | | | | Ataque | S. de | S. de | S. de | | | Nivel | base | Fort. | Ref. | Vol. | Especial | | 1. | +] | +2 | +0 | +0 | Analfabetismo, furia 1/día; movimiento rápido | | 2. | +2 | +3 | 40 | +0 | Esquiva asombrosa | | 3: | +3 | +3 | 手机 | +1 | Sentido de las trampas +1 | | 4° | +4 | +4 | +1 | +1 | Furia 2/día | | 5: | +5 | +4 | +1 | +1 | Esquiva asombrosa mejorada | | 6. | +6/+1 | +5 | +2 | +2 | Sentido de las trampas +2 | | 7. | +7/+2 | +5 | +2 | +2 | Reducción del daño 1/- | | 8. | +8/+3 | +6 | +2 | +2 | Furia 3/día | | 9: | +9/+4 | +6 | +3 | +3 | Sentido de las trampas +3 | | 10.º | +10/+5 | +7 | +3 | +3 | Reducción del daño 2/- | | 11. | +11/+6/+1 | +7 | +3 | +3 | Furia mayor | | 12. | +12/+7/+2 | +8 | +4 | +4 | Furia 4/día, sentido de las trampas +4 | | 13. | +13/48/43 | +8 | +4 | +4 | Reducción del daño 3/- | | 14: | +14/+9/+4 | +9 | +4 | +4 | Voluntad indomable | | 15. | +15/+10/+5 | +9 | +5 | +5 | Sentido de las trampas +5 | | 16. | +16/+11/+6/+1 | +10 | +5 | +5 | Furia 5/día, reducción del daño 4/ | | 17: | +77/+12/+7/+2 | +10 | +5 | +5 | Furia incansable | | 18. | +18/+13/+8/+3 | + 1 | +6 | +6 | Sentido de las trampas +6 | | 195 | +19/+14/+9/+4 | +17 | +6 | 46 | Reducción del daño 5/- | | 20.ª | +20/+15/+10/+5 | +12 | +6 | +6 | Furia 6/día, Furia poderosa | por una flecha, no podría dejarse llevar por la furia para ganar los puntos de golpe adicionales correspondientes al incremento en Constitución (se hubiera beneficiado de tales puntos en caso de haberse enfurecido en un momento anterior del combate, antes de ser golpeado por la flecha).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'furia' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro';
