update class_features set clazz = $c$Bárbaro$c$, kind = $c$Extraordinaria$c$, description = $c$A 2.º nivel, el bárbaro adquiere la aptitud de reaccionar ante el peligro antes de lo que sus sentidos le permitirían normalmente. Por ello retiene su bonificador de Destreza a la CA (en caso de tenerlo) incluso aunque le tomen desprevenido o sea atacado por un enemigo invisible. A pesar de ello seguirá perdiendo el bonificador de Destreza a la CA en caso de quedar inmovilizado. Si un bárbaro ya poseía esquiva asombrosa de una clase diferente (un bárbaro con al menos cuatro niveles de pícaro, por ejemplo), automáticamente obtiene esquiva asombrosa mejorada (ver más adelante) en su lugar.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'esquiva asombrosa' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Esquiva asombrosa$c$, $c$Bárbaro$c$, $c$Extraordinaria$c$, $c$A 2.º nivel, el bárbaro adquiere la aptitud de reaccionar ante el peligro antes de lo que sus sentidos le permitirían normalmente. Por ello retiene su bonificador de Destreza a la CA (en caso de tenerlo) incluso aunque le tomen desprevenido o sea atacado por un enemigo invisible. A pesar de ello seguirá perdiendo el bonificador de Destreza a la CA en caso de quedar inmovilizado. Si un bárbaro ya poseía esquiva asombrosa de una clase diferente (un bárbaro con al menos cuatro niveles de pícaro, por ejemplo), automáticamente obtiene esquiva asombrosa mejorada (ver más adelante) en su lugar.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'esquiva asombrosa' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro');
update class_features set clazz = $c$Bárbaro$c$, kind = $c$Extraordinaria$c$, description = $c$Comenzando a 3.ª nivel, el bárbaro adquiere un sentido intuitivo que le advierte de las trampas, lo que le concede un bonificador +1 a los TS de Reflejos realizados a fin de evitarlas, y un bonificador +1 de esquiva a la CA contra los ataques procedentes de ellas. Estos bonificadores aumentan en +1 por cada tres niveles de bárbaro posteriores (a nivel 6.º, 9.º, 12º, 15.ºy 18.º). Los bonificadores de sentido de las trampas ob tenidos de diferentes clases se apilan.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'sentido de las trampas' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Sentido de las trampas$c$, $c$Bárbaro$c$, $c$Extraordinaria$c$, $c$Comenzando a 3.ª nivel, el bárbaro adquiere un sentido intuitivo que le advierte de las trampas, lo que le concede un bonificador +1 a los TS de Reflejos realizados a fin de evitarlas, y un bonificador +1 de esquiva a la CA contra los ataques procedentes de ellas. Estos bonificadores aumentan en +1 por cada tres niveles de bárbaro posteriores (a nivel 6.º, 9.º, 12º, 15.ºy 18.º). Los bonificadores de sentido de las trampas ob tenidos de diferentes clases se apilan.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'sentido de las trampas' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro');
update class_features set clazz = $c$Bárbaro$c$, kind = $c$Extraordinaria$c$, description = $c$A partir del 5.º nivel, un bárbaro ya | no puede ser flanqueado, pues reaccionará ante oponentes situados a ambos lados con la misma facilidad que si tuviera que hacerlo ante un solo atacante. Esta defensa impedirá que un pícaro pueda atacar furtivamente al bárbaro cuando lo esté flanqueando, a no ser que el atacante tenga al menos cuatro niveles de pícaro más que los niveles de bárbaro del objetivo. Si un personaje ya tenía esquiva asombrosa (ver más arriba) de una segunda clase, automáticamente obtiene esquiva asombrosa mejorada en su lugar, y los niveles de todas las clases que proporcionan esquiva asombrosa se apilan para determinar el nivel mínimo de pícaro necesario para flanquear al personaje.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'esquiva asombrosa mejorada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Esquiva asombrosa mejorada$c$, $c$Bárbaro$c$, $c$Extraordinaria$c$, $c$A partir del 5.º nivel, un bárbaro ya | no puede ser flanqueado, pues reaccionará ante oponentes situados a ambos lados con la misma facilidad que si tuviera que hacerlo ante un solo atacante. Esta defensa impedirá que un pícaro pueda atacar furtivamente al bárbaro cuando lo esté flanqueando, a no ser que el atacante tenga al menos cuatro niveles de pícaro más que los niveles de bárbaro del objetivo. Si un personaje ya tenía esquiva asombrosa (ver más arriba) de una segunda clase, automáticamente obtiene esquiva asombrosa mejorada en su lugar, y los niveles de todas las clases que proporcionan esquiva asombrosa se apilan para determinar el nivel mínimo de pícaro necesario para flanquear al personaje.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'esquiva asombrosa mejorada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro');
update class_features set clazz = $c$Bárbaro$c$, kind = $c$Extraordinaria$c$, description = $c$A partir del nivel 7.º, un bárbaro obtiene la aptitud de ignorar parte del daño de cada golpe o ataque que reciba. Cada vez que el bárbaro sufra daño de un arma o ataque natural, resta 1 a la cantidad de puntos de golpe perdidos. A nivel 10.º y cada tres niveles de bárbaro adicionales (nivel 13.º, 16.ºy 19.º), la reducción del daño aumenta en 1 punto. Esta aptitud puede reducir el daño sufrido a 0, pero no a una cantidad inferior a 0.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'reduccion del dano' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Reducción del daño$c$, $c$Bárbaro$c$, $c$Extraordinaria$c$, $c$A partir del nivel 7.º, un bárbaro obtiene la aptitud de ignorar parte del daño de cada golpe o ataque que reciba. Cada vez que el bárbaro sufra daño de un arma o ataque natural, resta 1 a la cantidad de puntos de golpe perdidos. A nivel 10.º y cada tres niveles de bárbaro adicionales (nivel 13.º, 16.ºy 19.º), la reducción del daño aumenta en 1 punto. Esta aptitud puede reducir el daño sufrido a 0, pero no a una cantidad inferior a 0.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'reduccion del dano' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro');
update class_features set clazz = $c$Bárbaro$c$, kind = $c$Extraordinaria$c$, description = $c$A 11.º nivel, los bonificadores a Fuerza y Constitución de un bárbaro durante su furia aumentan a +6, y su bonificador de moral a las salvaciones de Voluntad aumenta a +3. El penalizador a la CA sigue siendo-2.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'furia mayor' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro';
