where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'furia mayor' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro');
update class_features set clazz = $c$Bárbaro$c$, kind = $c$Extraordinaria$c$, description = $c$Mientras esté enfurecido, un bárbaro de nivel 14.º o mayor obtiene un bonificador +4 a las salvaciones de Voluntad para resistir conjuros de encantamiento. Este bonificador se apila con todos los demás bonificadores, incluyendo el bonificador de moral a las salvaciones de Voluntad que recibe de manera normal durante la furia.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'voluntad indomable' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'barbaro';
