where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'contraoda' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'bardo');
update class_features set clazz = $c$Bardo$c$, kind = $c$Sobrenatural$c$, description = $c$Un bardo con 3 o más rangos en Interpretar podrá utilizar su canto o su poesía para infundir valor a sus aliados (incluido él mismo), fortaleciéndolos frente al miedo y mejorando sus aptitudes de combate. Para resultar afectado, el aliado debe oír la canción del bardo. El efecto se mantendrá mientras el bardo siga cantando y hasta 5 asaltos después de que termine de hacerlo. Los aliados afectados recibirán un bonificador +1 de moral a sus TS contra efectos de hechizar y miedo, y un bonificador +1 de moral a sus tiradas de ataque y daño. A 8.º nivel, y cada seis niveles de bardo adicionales, este bonificador aumenta en 1 (+2 a 8.9 +3 a 14.º y +4 a 20.º). Infundir valor es una aptitud enajenadora.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'infundir valor' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'bardo';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Infundir valor$c$, $c$Bardo$c$, $c$Sobrenatural$c$, $c$Un bardo con 3 o más rangos en Interpretar podrá utilizar su canto o su poesía para infundir valor a sus aliados (incluido él mismo), fortaleciéndolos frente al miedo y mejorando sus aptitudes de combate. Para resultar afectado, el aliado debe oír la canción del bardo. El efecto se mantendrá mientras el bardo siga cantando y hasta 5 asaltos después de que termine de hacerlo. Los aliados afectados recibirán un bonificador +1 de moral a sus TS contra efectos de hechizar y miedo, y un bonificador +1 de moral a sus tiradas de ataque y daño. A 8.º nivel, y cada seis niveles de bardo adicionales, este bonificador aumenta en 1 (+2 a 8.9 +3 a 14.º y +4 a 20.º). Infundir valor es una aptitud enajenadora.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'infundir valor' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'bardo');
update class_features set clazz = $c$Bardo$c$, kind = $c$Sobrenatural$c$, description = $c$Un bardo de nivel 3.º o superior con 6 o más rangos en Interpretar puede utilizar su música o su poesía para ayudar a un aliado a tener éxito en una tarea. El aliado debe ser capaz de verle y oírle, y no debe encontrarse a más de 30 de éste; además, el bardo debe estar viendo a su objetivo. Dependiendo de la tarea a realizar, el bardo puede valerse de su música mágica para ensalzar el espíritu de su aliado, hacer que se concentre o ayudarle de alguna otra forma. Mientras siga escuchando la música del bardo, el aliado de éste recibirá un bonificador +2 de capacidad en sus pruebas con una habilidad concreta. El DM puede decidir que algunos usos de esta aptitud son inverosímiles (cantar para que un pícaro se mueva mejor en silencio es una idea que cae por su propio peso ). El bardo puede mantener el efecto mientras se concentre, hasta un máximo de 2 minutos. No es posible que un bardo utilice esta aptitud sobre sí mismo. Infundir gran aptitud es una aptitud enajenadora. Sugestión (St): un bardo de 6.º nivel o superior con 9 o más rangos en Interpretar puede lanzar una sugestión (como el conjuro) sobre una criatura que previamente haya sido fascinada (ver más arriba). Utilizar esta aptitud no rompe la concentración del bardo sobre el efecto de fascinar, ni permite un segundo TS contra ese efecto. Realizar una sugestión no cuenta a la hora de calcular el límite de veces que el personaje puede utilizar la música de bardo cada día. Un IS de Voluntad (CD 10 + 1/2 del nivel de bardo + el modificador de Carisma del bardo) niega el efecto. Esta aptitud afecta a una única criatura (pero consulta sugestión en grupo, más adelante). Sugestión es una aptitud de encantamiento (compulsión), enajenadora y dependiente del idioma.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'infundir gran aptitud' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'bardo';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Infundir gran aptitud$c$, $c$Bardo$c$, $c$Sobrenatural$c$, $c$Un bardo de nivel 3.º o superior con 6 o más rangos en Interpretar puede utilizar su música o su poesía para ayudar a un aliado a tener éxito en una tarea. El aliado debe ser capaz de verle y oírle, y no debe encontrarse a más de 30 de éste; además, el bardo debe estar viendo a su objetivo. Dependiendo de la tarea a realizar, el bardo puede valerse de su música mágica para ensalzar el espíritu de su aliado, hacer que se concentre o ayudarle de alguna otra forma. Mientras siga escuchando la música del bardo, el aliado de éste recibirá un bonificador +2 de capacidad en sus pruebas con una habilidad concreta. El DM puede decidir que algunos usos de esta aptitud son inverosímiles (cantar para que un pícaro se mueva mejor en silencio es una idea que cae por su propio peso ). El bardo puede mantener el efecto mientras se concentre, hasta un máximo de 2 minutos. No es posible que un bardo utilice esta aptitud sobre sí mismo. Infundir gran aptitud es una aptitud enajenadora. Sugestión (St): un bardo de 6.º nivel o superior con 9 o más rangos en Interpretar puede lanzar una sugestión (como el conjuro) sobre una criatura que previamente haya sido fascinada (ver más arriba). Utilizar esta aptitud no rompe la concentración del bardo sobre el efecto de fascinar, ni permite un segundo TS contra ese efecto. Realizar una sugestión no cuenta a la hora de calcular el límite de veces que el personaje puede utilizar la música de bardo cada día. Un IS de Voluntad (CD 10 + 1/2 del nivel de bardo + el modificador de Carisma del bardo) niega el efecto. Esta aptitud afecta a una única criatura (pero consulta sugestión en grupo, más adelante). Sugestión es una aptitud de encantamiento (compulsión), enajenadora y dependiente del idioma.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'infundir gran aptitud' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'bardo');
update class_features set clazz = $c$Bardo$c$, kind = $c$Sobrenatural$c$, description = $c$Un bardo de 9.º nivel o superior con 12 o más rangos en Interpretar puede valerse del canto o de la poesía para infundir grandeza en sí mismo o en un único aliado voluntario en un radio de 30', concediéndole una mayor capacidad para la lucha. El bardo podrá afectar con un mismo uso. de esta aptitud a una criatura adicional por cada tres niveles en que supere el 9º (dos a nivel 12º, tres a 15º, cuatro a 18.º). Para infundir grandeza, el bardo debe cantar y el aliado debe escucharle. El efecto dura todo el tiempo que el aliado escuche cantar al bardo y los 5 asaltos siguientes. Una criatura a la que se infunda grandeza obtiene 2 DG adicionales (d10), el número correspondiente de puntos de golpe temporales (a estos DG adicionales se les debe aplicar el modificador de Constitución del objetivo, si existe), un bonificador +2 de competencia a las tiradas de ataque, y un bonificador +1 de competencia a las salvaciones de Fortaleza. Los DG adicionales cuentan como DG normales para determinar el efecto de conjuros como el de dormir. Infundir grandeza es una aptitud enajenadora. Canción de libertad (St): un bardo de 12.º nivel o superior con 15 o más rangos en Interpretar puede valerse del canto o de la poesía para crear un efecto equivalente al conjuro de romper encantamiento (el nivel de lanzador sería igual al nivel de bardo del personaje). Utilizar esta aptitud requiere 1 minuto de concentración ininterrumpida y música, y funciona sobre un único objetivo a no más de 30'. Un bardo no puede utilizar canción de libertad sobre sí mismo.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'infundir grandeza' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'bardo';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Infundir grandeza$c$, $c$Bardo$c$, $c$Sobrenatural$c$, $c$Un bardo de 9.º nivel o superior con 12 o más rangos en Interpretar puede valerse del canto o de la poesía para infundir grandeza en sí mismo o en un único aliado voluntario en un radio de 30', concediéndole una mayor capacidad para la lucha. El bardo podrá afectar con un mismo uso. de esta aptitud a una criatura adicional por cada tres niveles en que supere el 9º (dos a nivel 12º, tres a 15º, cuatro a 18.º). Para infundir grandeza, el bardo debe cantar y el aliado debe escucharle. El efecto dura todo el tiempo que el aliado escuche cantar al bardo y los 5 asaltos siguientes. Una criatura a la que se infunda grandeza obtiene 2 DG adicionales (d10), el número correspondiente de puntos de golpe temporales (a estos DG adicionales se les debe aplicar el modificador de Constitución del objetivo, si existe), un bonificador +2 de competencia a las tiradas de ataque, y un bonificador +1 de competencia a las salvaciones de Fortaleza. Los DG adicionales cuentan como DG normales para determinar el efecto de conjuros como el de dormir. Infundir grandeza es una aptitud enajenadora. Canción de libertad (St): un bardo de 12.º nivel o superior con 15 o más rangos en Interpretar puede valerse del canto o de la poesía para crear un efecto equivalente al conjuro de romper encantamiento (el nivel de lanzador sería igual al nivel de bardo del personaje). Utilizar esta aptitud requiere 1 minuto de concentración ininterrumpida y música, y funciona sobre un único objetivo a no más de 30'. Un bardo no puede utilizar canción de libertad sobre sí mismo.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'infundir grandeza' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'bardo');
update class_features set clazz = $c$Bardo$c$, kind = $c$Sobrenatural$c$, description = $c$Un bardo de 15.º nivel o superior con 18 o más rangos en Interpretar puede valerse del canto o de la poesía para infundir un tremendo heroísmo en sí mismo o en un único aliado voluntario a no más de 30', que permite a esa criatura luchar arrojadamente contra una oposición abrumadora. Por cada tres niveles de bardo que el personaje obtenga más allá del 15.º, puede infundir heroicidad en una criatura adicional. Para utilizar esta aptitud, el bardo debe cantar y el aliado debe escucharle durante un asalto completo. Una criatura a la que se le ha infundido heroicidad obtiene un bonificador +4 de moral en los TS y un bonificador +4 de esquiva a la CA. El efecto dura mientras el aliado escuche cantar al bardo y durante los 5 asaltos siguientes. Infundir heroicidad es una aptitud enajenadora. Sugestión en grupo (St): esta aptitud funciona como la de sugestión descrita antes, salvo en que un bardo de nivel 18.º o superior con 21 o más rangos en Interpretar puede realizar la sugestión simultáneamente sobre todas las criaturas que ya haya fascinado (ver más arriba). Sugestión en grupo es una aptitud de encantamiento (compulsión), enajenadora y dependiente del idioma.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'infundir heroicidad' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'bardo';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Infundir heroicidad$c$, $c$Bardo$c$, $c$Sobrenatural$c$, $c$Un bardo de 15.º nivel o superior con 18 o más rangos en Interpretar puede valerse del canto o de la poesía para infundir un tremendo heroísmo en sí mismo o en un único aliado voluntario a no más de 30', que permite a esa criatura luchar arrojadamente contra una oposición abrumadora. Por cada tres niveles de bardo que el personaje obtenga más allá del 15.º, puede infundir heroicidad en una criatura adicional. Para utilizar esta aptitud, el bardo debe cantar y el aliado debe escucharle durante un asalto completo. Una criatura a la que se le ha infundido heroicidad obtiene un bonificador +4 de moral en los TS y un bonificador +4 de esquiva a la CA. El efecto dura mientras el aliado escuche cantar al bardo y durante los 5 asaltos siguientes. Infundir heroicidad es una aptitud enajenadora. Sugestión en grupo (St): esta aptitud funciona como la de sugestión descrita antes, salvo en que un bardo de nivel 18.º o superior con 21 o más rangos en Interpretar puede realizar la sugestión simultáneamente sobre todas las criaturas que ya haya fascinado (ver más arriba). Sugestión en grupo es una aptitud de encantamiento (compulsión), enajenadora y dependiente del idioma.$c$, $c$Manual del Jugador 3.5$c$, 0
