update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$Un druida puede utilizar el lenguaje corporal, la vocalización y el comportamiento para mejorar la actitud de un animal (como un oso o un lagarto gigante). Esta aptitud funciona tal y como una prueba de Diplomacia realizada para mejorar la actitud de una persona (ver el Capítulo 4: habilidades). El druida tira 1d20 y suma su nivel de druida y su modificador de Carisma para determinar el resultado de la prueba de empatía salvaje. Un animal doméstico típico tiene una actitud inicial indiferente, mientras que los animales salvajes normalmente son malintencionados. Para utilizar la empatía animal, el druida y el animal deben ser capaces de estudiarse mutuamente, lo cual implica que en condiciones normales deben estar a un máximo de 30 pues el uno del otro. Generalmente, influenciar a un animal de este modo requiere 1 minuto pero, tal y como sucede al influenciar a personas, es posible que se requiera más o menos tiempo. Un druida también puede utilizar esta aptitud para influenciar a bestias mágicas con una puntuación de Inteligencia de 1 ó 2 (como un basilisco o un guiralón), pero en ese caso el druida recibe un penalizador -4 a la prueba.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'empatia salvaje' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Empatía salvaje$c$, $c$Druida$c$, $c$Extraordinaria$c$, $c$Un druida puede utilizar el lenguaje corporal, la vocalización y el comportamiento para mejorar la actitud de un animal (como un oso o un lagarto gigante). Esta aptitud funciona tal y como una prueba de Diplomacia realizada para mejorar la actitud de una persona (ver el Capítulo 4: habilidades). El druida tira 1d20 y suma su nivel de druida y su modificador de Carisma para determinar el resultado de la prueba de empatía salvaje. Un animal doméstico típico tiene una actitud inicial indiferente, mientras que los animales salvajes normalmente son malintencionados. Para utilizar la empatía animal, el druida y el animal deben ser capaces de estudiarse mutuamente, lo cual implica que en condiciones normales deben estar a un máximo de 30 pues el uno del otro. Generalmente, influenciar a un animal de este modo requiere 1 minuto pero, tal y como sucede al influenciar a personas, es posible que se requiera más o menos tiempo. Un druida también puede utilizar esta aptitud para influenciar a bestias mágicas con una puntuación de Inteligencia de 1 ó 2 (como un basilisco o un guiralón), pero en ese caso el druida recibe un penalizador -4 a la prueba.$c$, $c$Manual del Jugador 3.5$c$, 0
