update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$A partir de 2.º nivel, el druida podrá atravesar diversos terrenos naturales (arbustos espinosos, brezos, lugares cubiertos por la maleza y terreno similar) a velocidad normal y sin$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'zancada forestal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
