update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$Un druida puede controlar a su compañero animal como acción gratuita, o presionarle como una acción de movimiento, incluso aunque no tenga ningún rango en la habilidad de Trato con animales. El druida obtiene un bonificador +4 de circunstancia en todas las pruebas de empatía salvaje y Trato con animales realizadas con relación a un compañero animal.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'vinculo' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
