select $c$Vínculo$c$, $c$Druida$c$, $c$Extraordinaria$c$, $c$Un druida puede controlar a su compañero animal como acción gratuita, o presionarle como una acción de movimiento, incluso aunque no tenga ningún rango en la habilidad de Trato con animales. El druida obtiene un bonificador +4 de circunstancia en todas las pruebas de empatía salvaje y Trato con animales realizadas con relación a un compañero animal.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'vinculo' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida');
update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$Si el druida así lo decide, puede hacer que cualquier coniuro (pero no cualquier aptitud sortílega) que lance sobre sí mismo afecte también a su compañero animal. Para recibir el beneficio, el compañero animal no puede estar a más de 5' del druida en el momento de lanzar el conjuro. Si el conjuro o efecto tiene una duración distinta a instantáneo, deja de afectar al compañero animal si este se mueve a más de 5' de distancia (en este caso no volverá a afectarle aunque vuelva junto al druida antes de que expíre la duración del conjuro). Además, sufrir daño, o verse perjudicado de otro modo. Sin embargo, los terrenos que estén encantados o hayan sido manipulados mágicamente seguirán obstaculizando normalmente el avance del druida.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'compartir conjuros' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Compartir conjuros$c$, $c$Druida$c$, $c$Extraordinaria$c$, $c$Si el druida así lo decide, puede hacer que cualquier coniuro (pero no cualquier aptitud sortílega) que lance sobre sí mismo afecte también a su compañero animal. Para recibir el beneficio, el compañero animal no puede estar a más de 5' del druida en el momento de lanzar el conjuro. Si el conjuro o efecto tiene una duración distinta a instantáneo, deja de afectar al compañero animal si este se mueve a más de 5' de distancia (en este caso no volverá a afectarle aunque vuelva junto al druida antes de que expíre la duración del conjuro). Además, sufrir daño, o verse perjudicado de otro modo. Sin embargo, los terrenos que estén encantados o hayan sido manipulados mágicamente seguirán obstaculizando normalmente el avance del druida.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'compartir conjuros' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida');
update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$A partir del 3.6 nivel, el druida no dejará huellas cuando se mueva por entornos naturales y, por tanto, no podrá ser rastreado. Si lo desea, puede decidir dejar un rastro. el druida puede lanzar un conjuro con un objetivo de "tú" sobre su compañero animal (como si fuese un conjuro con alcance de toque) en lugar de sobre sí mismo. Un druida y su compañero animal pueden compartir conjuros incluso si el conjuro no afectaría normalmente a criaturas del tipo del compañero (animal).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'pisada sin rastro' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Pisada sin rastro$c$, $c$Druida$c$, $c$Extraordinaria$c$, $c$A partir del 3.6 nivel, el druida no dejará huellas cuando se mueva por entornos naturales y, por tanto, no podrá ser rastreado. Si lo desea, puede decidir dejar un rastro. el druida puede lanzar un conjuro con un objetivo de "tú" sobre su compañero animal (como si fuese un conjuro con alcance de toque) en lugar de sobre sí mismo. Un druida y su compañero animal pueden compartir conjuros incluso si el conjuro no afectaría normalmente a criaturas del tipo del compañero (animal).$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'pisada sin rastro' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida');
update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$Si un compañero animal sufre un ataque que normalmente permite un TS de Reflejos para medio daño, no recibe ningún daño si realiza la salvación con éxito.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
