where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida');
update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$La devoción de un compañero animal por su amo es tan completa que obtiene un bonificador +4 de moral en las salvaciones de Vol contra conjuros y efectos de encantamiento. Ataque múltiple: un compañero animal obtiene Ataque múltiple como dote adicional si tiene tres o más ataques naturales (consulta el Manual de monstruos para los detalles de esta dote) y todavía no la poseía. Si no tiene el requisito de poseer tres o más ataques naturales, el compañero animal obtiene en su lugar un segundo ataque con su arma natural principal, aunque con un penalizador de -5.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'devocion' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Devoción$c$, $c$Druida$c$, $c$Extraordinaria$c$, $c$La devoción de un compañero animal por su amo es tan completa que obtiene un bonificador +4 de moral en las salvaciones de Vol contra conjuros y efectos de encantamiento. Ataque múltiple: un compañero animal obtiene Ataque múltiple como dote adicional si tiene tres o más ataques naturales (consulta el Manual de monstruos para los detalles de esta dote) y todavía no la poseía. Si no tiene el requisito de poseer tres o más ataques naturales, el compañero animal obtiene en su lugar un segundo ataque con su arma natural principal, aunque con un penalizador de -5.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'devocion' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida');
update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$Cuando sufra un ataque que normalmente permite un TS de Reflejos para medio daño, un compañero animal no recibe daño alguno si supera el TS y sólo recibe medio daño si lo falla.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion mejorada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Evasión mejorada$c$, $c$Druida$c$, $c$Extraordinaria$c$, $c$Cuando sufra un ataque que normalmente permite un TS de Reflejos para medio daño, un compañero animal no recibe daño alguno si supera el TS y sólo recibe medio daño si lo falla.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion mejorada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida');
update class_features set clazz = $c$Druida$c$, kind = $c$Sobrenatural$c$, description = $c$A nivel 5.º, un druida adquiere la aptitud de transformarse en un animal Pequeño o Mediano y volver después a la forma humana una vez al día. Las posibles nuevas formas incluyen a todas las criaturas con el tipo "animal" (consulta el Manual de monstruos). Esta aptitud funciona como el conjuro de polimorfarse, salvo en lo que se señala aquí. El efecto dura 1 hora por nivel de druida, o hasta que el druida vuelve a su forma original. Cambiar de forma (a forma animal o de vuelta) es una acción estándar y no provoca ataques de oportunidad. La forma elegida debe ser la de un animal con el druida esté familiarizado. Por ejemplo, un druida que nunca haya estado fuera de un bosque templado no puede convertirse en un oso polar. Un druida pierde su capacidad para hablar mientras esté en forma animal, debido a que queda limitado a los sonidos que podría realizar un animal normal y no entrenado, aunque puede comunicarse de manera normal con otros animales del grupo general al que pertenezca su nueva forma (el sonido normal que hace un loro salvaje es un graznido, así que cambiar a esta forma no permite el habla. Tal y como se indica en la tabla 3-8: el druida, los de esta clase podrán utilizar esta aptitud más veces al día a medida que vayan alcanzando los niveles 6º, 7º, 10º, 14º y 18º. Además, a 8.º nivel el druida ganará la capacidad de adoptar la forma de un animal Grande; a 11.º, la de uno Menudo; y a 15., la de uno Enorme. Los Dados de golpe de la nueva forma no podrán exceder el nivel de druida del personaje. Por ejemplo, un druida no puede adoptar la forma de un oso terrible (una criatura Grande que siempre tiene 12 DG) hasta alcanzar el nivel 12, aunque puede comenzar a adoptar formas Grandes a 8.º nivel. A partir de nivel 12.º, un druida se vuelve capaz de utilizar forma salvaje paracambiar a la de una criatura tipo planta, como una broza movediza, con la misma restricción de tamaños que tenga para las formas animales (un druida no puede utilizar esta aptitud para adoptar la forma de una planta que no sea una criatura, como un árbol o un rosal). A nivel 16.º un druida también podrá utilizar esta aptitud para adoptar una vez al día la forma de un elemental de agua, aire, fuego o tierra, de tamaño Pequeño, Mediano o Grande. Estas formas elementales son un añadido a sus usos normales de forma salvaje. Además de los efectos normales de forma salvaje, el druida obtiene todas las aptitudes extraordinarias, sobrenaturales y sortílegas del elemental en cuestión. También obtiene las dotes del elemental mientras mantenga la forma salvaje, pero mantiene su propio tipo de criatura (humanoide, en la mayoría de los casos). A nivel 18.º un druida es capaz de asumir forma elemental dos veces por día, y a nivel 20.º puede hacerlo tres veces por día. A nivel 20.º, un druida puede utilizar su aptitud de forma salvaje para transformarse en un elemental Enorme.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'forma salvaje' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Forma salvaje$c$, $c$Druida$c$, $c$Sobrenatural$c$, $c$A nivel 5.º, un druida adquiere la aptitud de transformarse en un animal Pequeño o Mediano y volver después a la forma humana una vez al día. Las posibles nuevas formas incluyen a todas las criaturas con el tipo "animal" (consulta el Manual de monstruos). Esta aptitud funciona como el conjuro de polimorfarse, salvo en lo que se señala aquí. El efecto dura 1 hora por nivel de druida, o hasta que el druida vuelve a su forma original. Cambiar de forma (a forma animal o de vuelta) es una acción estándar y no provoca ataques de oportunidad. La forma elegida debe ser la de un animal con el druida esté familiarizado. Por ejemplo, un druida que nunca haya estado fuera de un bosque templado no puede convertirse en un oso polar. Un druida pierde su capacidad para hablar mientras esté en forma animal, debido a que queda limitado a los sonidos que podría realizar un animal normal y no entrenado, aunque puede comunicarse de manera normal con otros animales del grupo general al que pertenezca su nueva forma (el sonido normal que hace un loro salvaje es un graznido, así que cambiar a esta forma no permite el habla. Tal y como se indica en la tabla 3-8: el druida, los de esta clase podrán utilizar esta aptitud más veces al día a medida que vayan alcanzando los niveles 6º, 7º, 10º, 14º y 18º. Además, a 8.º nivel el druida ganará la capacidad de adoptar la forma de un animal Grande; a 11.º, la de uno Menudo; y a 15., la de uno Enorme. Los Dados de golpe de la nueva forma no podrán exceder el nivel de druida del personaje. Por ejemplo, un druida no puede adoptar la forma de un oso terrible (una criatura Grande que siempre tiene 12 DG) hasta alcanzar el nivel 12, aunque puede comenzar a adoptar formas Grandes a 8.º nivel. A partir de nivel 12.º, un druida se vuelve capaz de utilizar forma salvaje paracambiar a la de una criatura tipo planta, como una broza movediza, con la misma restricción de tamaños que tenga para las formas animales (un druida no puede utilizar esta aptitud para adoptar la forma de una planta que no sea una criatura, como un árbol o un rosal). A nivel 16.º un druida también podrá utilizar esta aptitud para adoptar una vez al día la forma de un elemental de agua, aire, fuego o tierra, de tamaño Pequeño, Mediano o Grande. Estas formas elementales son un añadido a sus usos normales de forma salvaje. Además de los efectos normales de forma salvaje, el druida obtiene todas las aptitudes extraordinarias, sobrenaturales y sortílegas del elemental en cuestión. También obtiene las dotes del elemental mientras mantenga la forma salvaje, pero mantiene su propio tipo de criatura (humanoide, en la mayoría de los casos). A nivel 18.º un druida es capaz de asumir forma elemental dos veces por día, y a nivel 20.º puede hacerlo tres veces por día. A nivel 20.º, un druida puede utilizar su aptitud de forma salvaje para transformarse en un elemental Enorme.$c$, $c$Manual del Jugador 3.5$c$, 0
