update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$A 9.º nivel, un druida se vuelve inmune a todos los venenos.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'inmunidad al veneno' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
