where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'inmunidad al veneno' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida');
update class_features set clazz = $c$Druida$c$, kind = $c$Sobrenatural$c$, description = $c$Al alcanzar el nivel 13°, un druida obtiene la aptitud de cambiar su aspecto a voluntad como si estuviera utilizando el conjuro alterar el propio aspecto (pág. 199), pero sólo mientras esté en su forma normal.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'las mil caras' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Las mil caras$c$, $c$Druida$c$, $c$Sobrenatural$c$, $c$Al alcanzar el nivel 13°, un druida obtiene la aptitud de cambiar su aspecto a voluntad como si estuviera utilizando el conjuro alterar el propio aspecto (pág. 199), pero sólo mientras esté en su forma normal.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'las mil caras' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida');
update class_features set clazz = $c$Druida$c$, kind = $c$Extraordinaria$c$, description = $c$A partir de nivel 15.º, el druida ya no sufre penalizadores a las características por causa de la edad (consulta la tabla 6-5: efectos del envejecimiento, en la pág. 109) y tampoco se le puede hacer envejecer utilizando medios mágicos; sin embargo, no se librará de los penalizadores que ya sufriera. El personaje seguirá acumulando los bonificadores debidos al envejecimiento y morirá de viejo cuando le llegue la hora.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'cuerpo eterno' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Cuerpo eterno$c$, $c$Druida$c$, $c$Extraordinaria$c$, $c$A partir de nivel 15.º, el druida ya no sufre penalizadores a las características por causa de la edad (consulta la tabla 6-5: efectos del envejecimiento, en la pág. 109) y tampoco se le puede hacer envejecer utilizando medios mágicos; sin embargo, no se librará de los penalizadores que ya sufriera. El personaje seguirá acumulando los bonificadores debidos al envejecimiento y morirá de viejo cuando le llegue la hora.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'cuerpo eterno' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'druida');
update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$En el 1.ª nivel, el explorador puede escoger un tipo de criatura de entre las de la tabla 3-10: enemigos predilectos. del explorador. Gracias al minucioso estudio de sus enemigos y al entrenamiento en las técnicas adecuadas para combatirlos, el explorador gana un bonificador +2 en las pruebas de Averiguar intenciones, Avistar, Engañar, Escuchar y Supervivencia cuando utiliza tales habilidades contra las criaturas de ese tipo. De un modo similar, recibe un bonificador +2 en las tiradas de daño con armas contra ese tipo de criaturas. Al alcanzar el 5.º nivel, y cada cinco niveles a partir de entonces (10.º, 15.º y 20.º), el explorador podrá elegir un nuevo enemigo predilecto de los de la tabla. Además, en cada una de estas ocasiones, el bonificador que posea contra un único tipo de enemigo predilecto (incluido el que acaba de elegit, si así lo desea) se incrementará en +2. Por ejemplo, un explorador de 5.º nivel tiene dos enemigos predilectos; contra uno obtiene un bonificador +4 en las pruebas de Averiguar intenciones, Avistar, Engañar, Escuchar y Supervivencia y en las tiradas de daño, y contra el otro tiene un +2. A nivel 10.º tiene tres enemigos predilectos, y obtiene un bonificador +2 adicional que puede adjudicar a cualquiera de sus tres enemigos predilectos. Así, los bonificadores podrían ser +4, +4, +2 o +6, +2, +2. Si el explorador elige humanoides o ajenos como enemigos predilectos, también debe elegir un subtipo asociado, tal y como se indica en la tabla. Si una criatura específica cae dentro de más de una categoría de enemigo predilecto (por ejemplo, los diablos son tanto ajenos malignos como ajenos legales), los bonificadores del explorador no se apilan, sino que se limita a utilizar el bonificador mayor. Consulta el Manual de monstruos para obtener más información sobre los tipos de criaturas.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'enemigo predilecto' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Enemigo predilecto$c$, $c$Explorador$c$, $c$Extraordinaria$c$, $c$En el 1.ª nivel, el explorador puede escoger un tipo de criatura de entre las de la tabla 3-10: enemigos predilectos. del explorador. Gracias al minucioso estudio de sus enemigos y al entrenamiento en las técnicas adecuadas para combatirlos, el explorador gana un bonificador +2 en las pruebas de Averiguar intenciones, Avistar, Engañar, Escuchar y Supervivencia cuando utiliza tales habilidades contra las criaturas de ese tipo. De un modo similar, recibe un bonificador +2 en las tiradas de daño con armas contra ese tipo de criaturas. Al alcanzar el 5.º nivel, y cada cinco niveles a partir de entonces (10.º, 15.º y 20.º), el explorador podrá elegir un nuevo enemigo predilecto de los de la tabla. Además, en cada una de estas ocasiones, el bonificador que posea contra un único tipo de enemigo predilecto (incluido el que acaba de elegit, si así lo desea) se incrementará en +2. Por ejemplo, un explorador de 5.º nivel tiene dos enemigos predilectos; contra uno obtiene un bonificador +4 en las pruebas de Averiguar intenciones, Avistar, Engañar, Escuchar y Supervivencia y en las tiradas de daño, y contra el otro tiene un +2. A nivel 10.º tiene tres enemigos predilectos, y obtiene un bonificador +2 adicional que puede adjudicar a cualquiera de sus tres enemigos predilectos. Así, los bonificadores podrían ser +4, +4, +2 o +6, +2, +2. Si el explorador elige humanoides o ajenos como enemigos predilectos, también debe elegir un subtipo asociado, tal y como se indica en la tabla. Si una criatura específica cae dentro de más de una categoría de enemigo predilecto (por ejemplo, los diablos son tanto ajenos malignos como ajenos legales), los bonificadores del explorador no se apilan, sino que se limita a utilizar el bonificador mayor. Consulta el Manual de monstruos para obtener más información sobre los tipos de criaturas.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'enemigo predilecto' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador');
update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$Un explorador puede utilizar el lenguaje corporal, la vocalización y el comportamiento para mejorar la actitud de un animal (como un oso o un lagarto gigante). Esta aptitud funciona como una prueba de Diplomacia realizada para mejorar la actitud de una persona (ver pág. 71). El explorador tira 1d20 y suma su nivel de explorador y su modificador de Carisma para determinar el resultado de la prueba de empatía salvaje. Un animal doméstico típico tiene una actitud inicial de indiferente, mientras que los animales salvajes normalmente son malintencionados. Para utilizar la empatía salvaje, el explorador y el animal deben ser capaces de estudiarse mutuamente, lo cual implica que en condiciones normales deben estar a un máximo de 30' el uno del otro. Generalmente, influenciar a un animal de este modo requiere 1 minuto pero, como sucede al influenciar a personas, es posible que se requiera más o menos tiempo. Un explorador también puede utilizar esta aptitud para influenciar a bestias mágicas con una puntuación de Inteligencia de 1 ó 2 (como un basilisco o un guiralón), pero en ese caso el explorador recibe un penalizador de - 4 a la prueba.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'empatia salvaje' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Empatía salvaje$c$, $c$Explorador$c$, $c$Extraordinaria$c$, $c$Un explorador puede utilizar el lenguaje corporal, la vocalización y el comportamiento para mejorar la actitud de un animal (como un oso o un lagarto gigante). Esta aptitud funciona como una prueba de Diplomacia realizada para mejorar la actitud de una persona (ver pág. 71). El explorador tira 1d20 y suma su nivel de explorador y su modificador de Carisma para determinar el resultado de la prueba de empatía salvaje. Un animal doméstico típico tiene una actitud inicial de indiferente, mientras que los animales salvajes normalmente son malintencionados. Para utilizar la empatía salvaje, el explorador y el animal deben ser capaces de estudiarse mutuamente, lo cual implica que en condiciones normales deben estar a un máximo de 30' el uno del otro. Generalmente, influenciar a un animal de este modo requiere 1 minuto pero, como sucede al influenciar a personas, es posible que se requiera más o menos tiempo. Un explorador también puede utilizar esta aptitud para influenciar a bestias mágicas con una puntuación de Inteligencia de 1 ó 2 (como un basilisco o un guiralón), pero en ese caso el explorador recibe un penalizador de - 4 a la prueba.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'empatia salvaje' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador');
update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$A 2.º nivel, un explorador debe elegir qué estilo de combate desea seguir de entre dos opciones: tiro con arco o combate con dos armas. Esta elección afecta a los rasgos de clase del personaje pero no restringe su selección de dotes o aptitudes especiales de modo alguno. Si el explorador elige tiro con arco, se considera que posee la dote Disparo rápido, incluso si no reúne los prerrequisitos normales de esta. Si elige combate con dos armas, se considera que posee la dote Comba- te con dos armas, incluso si no reúne los prerrequisitos normales de esta. Los beneficios del estilo elegido por el explorador sólo se aplican cuando éste lleva armadura ligera o va sin armadura. Pierde todos los beneficios de su estilo de combate si lleva armadura intermedia o pesada. Aguante: un explorador obtiene Aguante (pág. 89) como dote adicional a 3.ª nivel.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'estilo de combate' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Estilo de combate$c$, $c$Explorador$c$, $c$Extraordinaria$c$, $c$A 2.º nivel, un explorador debe elegir qué estilo de combate desea seguir de entre dos opciones: tiro con arco o combate con dos armas. Esta elección afecta a los rasgos de clase del personaje pero no restringe su selección de dotes o aptitudes especiales de modo alguno. Si el explorador elige tiro con arco, se considera que posee la dote Disparo rápido, incluso si no reúne los prerrequisitos normales de esta. Si elige combate con dos armas, se considera que posee la dote Comba- te con dos armas, incluso si no reúne los prerrequisitos normales de esta. Los beneficios del estilo elegido por el explorador sólo se aplican cuando éste lleva armadura ligera o va sin armadura. Pierde todos los beneficios de su estilo de combate si lleva armadura intermedia o pesada. Aguante: un explorador obtiene Aguante (pág. 89) como dote adicional a 3.ª nivel.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'estilo de combate' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador');
update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$A 4.º nivel, un explorador obtiene un compañero animal, elegido de la siguiente lista: águila, búho, caballo (ligero o pesado), camello, halcón, lobo, perro, perro de monta, poni, rata terrible, serpiente (víbora Pequeña o Mediana) o tejón. Si la campaña del DM tiene lugar parcial o totalmente en un entorno acuático, este puede añadir las siguientes criaturas a la lista de opciones del explorador: calamar, marsopa y tiburón Mediano. Este animal es un camarada leal que acompaña al explorador en sus aventuras tal y como sea apropiado para su especie (por ejemplo, una criatura acuática no puede acompañar al explorador en aventuras terrestres y no debería ser elegida por un personaje no acuático sin que medien circunstancias excepcionales). En la mayoría de los casos, el compañero animal actúa como una montura, centinela, batidor o animal de caza, más que como protector. Esta aptitud funciona como la aptitud de druida del mismo nombre (ver pág. 35), salvo en que el nivel efectivo de druida del explorador es la mitad de su nivel de explorador. Por ejemplo, el compañero animal de un explorador de 4.º nivel sería el equivalente al compañero animal de un druida de 2.º nivel. Un explorador puede elegir de una lista alternativa de compañeros animales tal y como pueden hacer los druidas, aunque de nuevo su nivel efectivo de druida es la mitad de su nivel de explorador. Así, debe ser al menos un explorador de 8.º nivel para elegir de la lista de druida de compañeros animales para 4.º nivel, y si elige uno de estos animales su nivel efectivo de druida se verá reducido en 3, hasta 1.4 nivel. Como les sucede a los druidas, un explorador no puede elegir un animal alternativo si su elección reduciría su nivel efectivo de druida por debajo del 1.º. Conjuros: a partir del 4.º nivel, el explorador adquiere la aptitud de lanzar una pequeña cantidad de conjuros de magia divina (el mismo tipo disponible al clérigo, druida y paladín), elegidos de la lista de conjuros del explorador (pág. 191). Un explorador debe elegir y preparar sus conjuros con ante ación (ver más adelante). Para preparar o lanzar un conjuro, el personaje ha de tener una puntuación en Sabiduría igual o superior a 10 + el nivel del conjuro (Sab 10 para conjuros de 1.ª nivel, Sab 12 para conjuros de 2.º nivel, etc). La Clase de dificultad de las salvaciones contra los conjuros de explorador es 10 + el nivel del conjuro + el modificador de Sabiduría del explorador. Como otros lanzadores de conjuros, un explorador sólo puede lanzar un número determinado de conjuros de cada nivel por día. Su asignación diaria de conjuros se da en la tabla 3-9: el explorador. Además, recibe con- juros diarios adicionales si tiene una puntuación alta de Sabiduría (ver la tabla 1-1: modificadores de característica y conjuros adicionales, pág. 8). Cuando la tabla 3-6 indica que el explorador obtiene 0 conjuros por día de un determinado nivel de conjuros (por ejemplo, conjuros de 1.5 nivel para un explorador de 4.º nivel), solamente obtiene los conjuros adicionales para ese nivel correspondientes a su puntuación de Sabiduría. A diferencia del clérigo, el explorador no tiene acceso a ningún conjuro ni poder garantizado de dominio. Un explorador prepara y lanza conjuros del mismo modo que lo hace un clérigo, aunque no puede perder un conjuro preparado para lanzar un conjuro de curar en su lugar. Un explorador puede preparar y lanzar cualquier conjuro de la lista de conjuros de explorador, suponiendo que pueda lanzar conjuros de ese nivel, aunque durante la meditación de ese día deberá elegir qué conjuros va a preparar. Hasta 3.ª nivel un explorador no tiene nivel de lanzador, y a partir de 4.º nivel su nivel de lanzador es la mitad de su nivel de explorador.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'companero animal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Compañero animal$c$, $c$Explorador$c$, $c$Extraordinaria$c$, $c$A 4.º nivel, un explorador obtiene un compañero animal, elegido de la siguiente lista: águila, búho, caballo (ligero o pesado), camello, halcón, lobo, perro, perro de monta, poni, rata terrible, serpiente (víbora Pequeña o Mediana) o tejón. Si la campaña del DM tiene lugar parcial o totalmente en un entorno acuático, este puede añadir las siguientes criaturas a la lista de opciones del explorador: calamar, marsopa y tiburón Mediano. Este animal es un camarada leal que acompaña al explorador en sus aventuras tal y como sea apropiado para su especie (por ejemplo, una criatura acuática no puede acompañar al explorador en aventuras terrestres y no debería ser elegida por un personaje no acuático sin que medien circunstancias excepcionales). En la mayoría de los casos, el compañero animal actúa como una montura, centinela, batidor o animal de caza, más que como protector. Esta aptitud funciona como la aptitud de druida del mismo nombre (ver pág. 35), salvo en que el nivel efectivo de druida del explorador es la mitad de su nivel de explorador. Por ejemplo, el compañero animal de un explorador de 4.º nivel sería el equivalente al compañero animal de un druida de 2.º nivel. Un explorador puede elegir de una lista alternativa de compañeros animales tal y como pueden hacer los druidas, aunque de nuevo su nivel efectivo de druida es la mitad de su nivel de explorador. Así, debe ser al menos un explorador de 8.º nivel para elegir de la lista de druida de compañeros animales para 4.º nivel, y si elige uno de estos animales su nivel efectivo de druida se verá reducido en 3, hasta 1.4 nivel. Como les sucede a los druidas, un explorador no puede elegir un animal alternativo si su elección reduciría su nivel efectivo de druida por debajo del 1.º. Conjuros: a partir del 4.º nivel, el explorador adquiere la aptitud de lanzar una pequeña cantidad de conjuros de magia divina (el mismo tipo disponible al clérigo, druida y paladín), elegidos de la lista de conjuros del explorador (pág. 191). Un explorador debe elegir y preparar sus conjuros con ante ación (ver más adelante). Para preparar o lanzar un conjuro, el personaje ha de tener una puntuación en Sabiduría igual o superior a 10 + el nivel del conjuro (Sab 10 para conjuros de 1.ª nivel, Sab 12 para conjuros de 2.º nivel, etc). La Clase de dificultad de las salvaciones contra los conjuros de explorador es 10 + el nivel del conjuro + el modificador de Sabiduría del explorador. Como otros lanzadores de conjuros, un explorador sólo puede lanzar un número determinado de conjuros de cada nivel por día. Su asignación diaria de conjuros se da en la tabla 3-9: el explorador. Además, recibe con- juros diarios adicionales si tiene una puntuación alta de Sabiduría (ver la tabla 1-1: modificadores de característica y conjuros adicionales, pág. 8). Cuando la tabla 3-6 indica que el explorador obtiene 0 conjuros por día de un determinado nivel de conjuros (por ejemplo, conjuros de 1.5 nivel para un explorador de 4.º nivel), solamente obtiene los conjuros adicionales para ese nivel correspondientes a su puntuación de Sabiduría. A diferencia del clérigo, el explorador no tiene acceso a ningún conjuro ni poder garantizado de dominio. Un explorador prepara y lanza conjuros del mismo modo que lo hace un clérigo, aunque no puede perder un conjuro preparado para lanzar un conjuro de curar en su lugar. Un explorador puede preparar y lanzar cualquier conjuro de la lista de conjuros de explorador, suponiendo que pueda lanzar conjuros de ese nivel, aunque durante la meditación de ese día deberá elegir qué conjuros va a preparar. Hasta 3.ª nivel un explorador no tiene nivel de lanzador, y a partir de 4.º nivel su nivel de lanzador es la mitad de su nivel de explorador.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'companero animal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador');
update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$A 6.º nivel, las capacidades de un explorador en el estilo de combate elegido (tiro con arco o combate con dos armas) mejoran. Si eligió tiro con arco a 2.º nivel, se considera que posee la dote Disparos múltiples (pág. 96), incluso aunque no reúna los prerrequisitos normales para ella. Si el explorador eligió combate con dos armas a 2.º nivel, se considera como si tuviese la dote Combate con dos armas mejorado (pág. 92), incluso aunque no reúna los prerrequisitos necesarios para ella. Como antes, los beneficios del estilo elegido por el explorador sólo se aplican cuando lleva armadura ligera o va sin armadura. Pierde todos los beneficios si lleva armadura intermedia o pesada.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'estilo de combate mejorado' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Estilo de combate mejorado$c$, $c$Explorador$c$, $c$Extraordinaria$c$, $c$A 6.º nivel, las capacidades de un explorador en el estilo de combate elegido (tiro con arco o combate con dos armas) mejoran. Si eligió tiro con arco a 2.º nivel, se considera que posee la dote Disparos múltiples (pág. 96), incluso aunque no reúna los prerrequisitos normales para ella. Si el explorador eligió combate con dos armas a 2.º nivel, se considera como si tuviese la dote Combate con dos armas mejorado (pág. 92), incluso aunque no reúna los prerrequisitos necesarios para ella. Como antes, los beneficios del estilo elegido por el explorador sólo se aplican cuando lleva armadura ligera o va sin armadura. Pierde todos los beneficios si lleva armadura intermedia o pesada.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'estilo de combate mejorado' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador');
update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$A partir de 7.º nivel, el explorador podrá atravesar diversos terrenos naturales (arbustos espinosos, brezos, lugares cubiertos por la maleza, etc.) a velocidad normal y sin sufrir daños, o verse perjudicado de otro modo. Sin embargo, los terrenos citados que estén encantados o hayan sido manipulados mágicamente seguirán obstaculizando normalmente el avance del explorador.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'zancada forestal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Zancada forestal$c$, $c$Explorador$c$, $c$Extraordinaria$c$, $c$A partir de 7.º nivel, el explorador podrá atravesar diversos terrenos naturales (arbustos espinosos, brezos, lugares cubiertos por la maleza, etc.) a velocidad normal y sin sufrir daños, o verse perjudicado de otro modo. Sin embargo, los terrenos citados que estén encantados o hayan sido manipulados mágicamente seguirán obstaculizando normalmente el avance del explorador.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'zancada forestal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador');
update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$Comenzando a 8.º nivel, un explorador puede moverse a su velocidad normal mientras esté siguiendo rastros sin sufrir el penalizador -5 normal. Solamente recibe un penalizador-10 (en lugar del-20 normal) cuando se mueve al doble de su velocidad normal mientras rastrea.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'rastreador veloz' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Rastreador veloz$c$, $c$Explorador$c$, $c$Extraordinaria$c$, $c$Comenzando a 8.º nivel, un explorador puede moverse a su velocidad normal mientras esté siguiendo rastros sin sufrir el penalizador -5 normal. Solamente recibe un penalizador-10 (en lugar del-20 normal) cuando se mueve al doble de su velocidad normal mientras rastrea.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'rastreador veloz' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador');
update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$A 9.º nivel, un explorador puede evitar incluso los ataques mágicos o insólitos gracias a su gran agilidad. El explorador no sufre daño alguno cuando pasa un TS de Reflejos contra un ataque que normalmente infligiría la mitad del daño con un tiro con éxito (como el terrible aliento de un dragón rojo o una bola de fuego). Esta aptitud extraordinaria sólo puede utilizarse cuando el explorador viste armadura ligera o no lleva ninguna. Un explorador indefenso (paralizado o inconsciente, por ejemplo) no obtiene el beneficio de evasión. Maestría con el estilo de combate (Ex): a 11.º nivel, las habilidades del explorador en el estilo de combate elegido (tiro con arco o combate con dos armas) mejoran de nuevo. Si eligió tiro con arco a 2.º nivel, se considera que posee la dote Disparo preciso mejorado (pág. 95), incluso aunque no reúna los prerrequisitos normales para ella. Si el explorador eligió combate con dos armas a 2.º nivel, se considera como si tuviese la dote Combate con dos armas mayor (pág. 92), incluso aunque no reúna los prerrequisitos necesarios para ella. Como antes, los beneficios del estilo elegido por el explorador sólo se aplican cuando lleva armadura ligera o va sin armadura. Pierde todos los beneficios si lleva una armadura intermedia o pesada. LOCKWOOD$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Evasión$c$, $c$Explorador$c$, $c$Extraordinaria$c$, $c$A 9.º nivel, un explorador puede evitar incluso los ataques mágicos o insólitos gracias a su gran agilidad. El explorador no sufre daño alguno cuando pasa un TS de Reflejos contra un ataque que normalmente infligiría la mitad del daño con un tiro con éxito (como el terrible aliento de un dragón rojo o una bola de fuego). Esta aptitud extraordinaria sólo puede utilizarse cuando el explorador viste armadura ligera o no lleva ninguna. Un explorador indefenso (paralizado o inconsciente, por ejemplo) no obtiene el beneficio de evasión. Maestría con el estilo de combate (Ex): a 11.º nivel, las habilidades del explorador en el estilo de combate elegido (tiro con arco o combate con dos armas) mejoran de nuevo. Si eligió tiro con arco a 2.º nivel, se considera que posee la dote Disparo preciso mejorado (pág. 95), incluso aunque no reúna los prerrequisitos normales para ella. Si el explorador eligió combate con dos armas a 2.º nivel, se considera como si tuviese la dote Combate con dos armas mayor (pág. 92), incluso aunque no reúna los prerrequisitos necesarios para ella. Como antes, los beneficios del estilo elegido por el explorador sólo se aplican cuando lleva armadura ligera o va sin armadura. Pierde todos los beneficios si lleva una armadura intermedia o pesada. LOCKWOOD$c$, $c$Manual del Jugador 3.5$c$, 0
