update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$Un explorador de nivel 13.º o superior puede utilizar la habilidad de Esconderse en cualquier tipo de terreno natural, incluso si el terreno no proporciona cobertura ni ocultación.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'camuflaje' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
