update class_features set clazz = $c$Explorador$c$, kind = $c$Extraordinaria$c$, description = $c$Mientras esté en algún tipo de terre no natural, un explorador de nivel 17.º o superior puede utilizar la aptitud de Esconderse incluso mientras esté siendo observado.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'esconderse a plena vista' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'explorador';
