select $c$Evasión$c$, $c$Monje$c$, $c$Extraordinaria$c$, $c$A partir de 2.º nivel, un monje puede evitar hasta los ataques mágicos o insólitos gracias a su gran agilidad. Los monjes no sufren daño alguno cuando pasan un TS de Reflejos contra un ataque que normalmente infligiría la mitad del daño con un tiro con éxito (como el terrible aliento de un dragón rojo o una bola de fuego). La evasión sólo puede utilizarse cuando el monje viste armadura ligera o ninguna armadura. Un monje indefenso (si está inconsciente o paralizado, por ejemplo), no l puede beneficiarse de esta aptitud.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje');
update class_features set clazz = $c$Monje$c$, kind = $c$Extraordinaria$c$, description = $c$A partir de 3.5 nivel, un monje obtiene un bonificador de mejora a su velocidad, tal y como se muestra en la tabla 3-15. Un monje que vista armadura (aunque sea ligera) o lleve una carga intermedia o pesada perderá esta velocidad adicional.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'movimiento rapido' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
