update class_features set clazz = $c$Monje$c$, kind = $c$Extraordinaria$c$, description = $c$Al alcanzar el 3.6 nivel, un monje gana un bonificador +2 en sus TS contra conjuros y efectos de la escuela de encantamiento, pues su meditación y su entrenamiento le permiten oponer mayor resistencia a los ataques enajenadores.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'mente en calma' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
