where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'mente en calma' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje');
update class_features set clazz = $c$Monje$c$, kind = $c$Sobrenatural$c$, description = $c$Al alcanzar el 4.º nivel, el ataque sin arma del monje se ve potenciado con el ki. Sus ataques sin arma son considerados como armas mágicas a efectos de causar daño a criaturas con reducción del daño (ver 'Reducción del daño' en la Guía del Dungeon Master). El impacto ki mejora con el nivel del monje. A 10.º nivel, sus impactos sin armas se consideran también armas legales a efectos de infligir daño a criaturas con reducción del daño. A nivel 16.º, sus impactos sin arma son considerados armas adamantinas a efectos de causar daño a criaturas con reducción del daño y para superar la dureza (consulta 'Hacer pedazos un objeto', pág. 165).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'impacto ki' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Impacto ki$c$, $c$Monje$c$, $c$Sobrenatural$c$, $c$Al alcanzar el 4.º nivel, el ataque sin arma del monje se ve potenciado con el ki. Sus ataques sin arma son considerados como armas mágicas a efectos de causar daño a criaturas con reducción del daño (ver 'Reducción del daño' en la Guía del Dungeon Master). El impacto ki mejora con el nivel del monje. A 10.º nivel, sus impactos sin armas se consideran también armas legales a efectos de infligir daño a criaturas con reducción del daño. A nivel 16.º, sus impactos sin arma son considerados armas adamantinas a efectos de causar daño a criaturas con reducción del daño y para superar la dureza (consulta 'Hacer pedazos un objeto', pág. 165).$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'impacto ki' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje');
update class_features set clazz = $c$Monje$c$, kind = $c$Extraordinaria$c$, description = $c$Al alcanzar el 4.º nivel y superiores, los monjes pueden aprovechar las paredes que tengan a su alcance para ralentizar sus caídas, sufriendo daño como si la caída en cuestión tuviera 20 menos de los que tiene en realidad. La aptitud del monje para ralentizar las caídas (es decir, reducir la altura efectiva de las caídas cuando se encuentra cerca de una pared) mejora nivel a nivel hasta que, al alcanzar el 20.º, el personaje puede valerse de los muros próximos para ralentizar su caída y caer desde cualquier altura sin sufrir daño alguno. Para obtener más detalles, consulta la columna "Especial' de la tabla 3-15.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'caida ralentizada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Caída ralentizada$c$, $c$Monje$c$, $c$Extraordinaria$c$, $c$Al alcanzar el 4.º nivel y superiores, los monjes pueden aprovechar las paredes que tengan a su alcance para ralentizar sus caídas, sufriendo daño como si la caída en cuestión tuviera 20 menos de los que tiene en realidad. La aptitud del monje para ralentizar las caídas (es decir, reducir la altura efectiva de las caídas cuando se encuentra cerca de una pared) mejora nivel a nivel hasta que, al alcanzar el 20.º, el personaje puede valerse de los muros próximos para ralentizar su caída y caer desde cualquier altura sin sufrir daño alguno. Para obtener más detalles, consulta la columna "Especial' de la tabla 3-15.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'caida ralentizada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje');
update class_features set clazz = $c$Monje$c$, kind = $c$Extraordinaria$c$, description = $c$Al alcanzar el 5.º nivel, un monje adquiere el control de su sistema inmunológico; por tanto, su organismo se inmuniza contra todas las enfermedades, exceptuando aquellas que tengan naturaleza mágica, como la putridez de momia o la licantropía.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'pureza corporal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Pureza corporal$c$, $c$Monje$c$, $c$Extraordinaria$c$, $c$Al alcanzar el 5.º nivel, un monje adquiere el control de su sistema inmunológico; por tanto, su organismo se inmuniza contra todas las enfermedades, exceptuando aquellas que tengan naturaleza mágica, como la putridez de momia o la licantropía.$c$, $c$Manual del Jugador 3.5$c$, 0
