update class_features set clazz = $c$Monje$c$, kind = $c$Sobrenatural$c$, description = $c$Al alcanzar el 7.º nivel, un monje puede curar sus propias heridas. Esta aptitud le permite recuperar al día una cantidad de puntos de golpe equivalente al doble de su nivel de experiencia, pudiendo repartir el efecto curativo entre varios usos.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'plenitud corporal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Plenitud corporal$c$, $c$Monje$c$, $c$Sobrenatural$c$, $c$Al alcanzar el 7.º nivel, un monje puede curar sus propias heridas. Esta aptitud le permite recuperar al día una cantidad de puntos de golpe equivalente al doble de su nivel de experiencia, pudiendo repartir el efecto curativo entre varios usos.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'plenitud corporal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje');
update class_features set clazz = $c$Monje$c$, kind = $c$Extraordinaria$c$, description = $c$Al alcanzar el 9.º nivel, la aptitud de evasión del monje mejora. Seguirá sin suftir daño cuanto tenga éxito en un TS contra ataques como el arma de aliento de un dragón o una bola de fuego, pero a partir de ahora sólo sufrirá la mitad de daño aunque falle las tiradas. Un monje indefenso (si está inconsciente o paralizado, por ejemplo), no puede beneficiarse de esta aptitud.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion mejorada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
