update class_features set clazz = $c$Monje$c$, kind = $c$Sobrenatural$c$, description = $c$Al alcanzar el 11.º nivel, un monje posee tal control sobre su metabolismo que se inmuniza contra todo tipo de venenos.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'cuerpo diamantino' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
