update class_features set clazz = $c$Monje$c$, kind = $c$Sobrenatural$c$, description = $c$Al alcanzar el 12.º nivel, un monje puede deslizarse mágicamente entre espacios, como al utilizar el conjuro puerta dimensional, una vez al día. Su nivel de lanzador para este efecto es la mitad de su nivel de monje (redondeando a la baja).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'paso abundante' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
insert into class_features (name, clazz, kind, description, source, level)
