update class_features set clazz = $c$Monje$c$, kind = $c$Extraordinaria$c$, description = $c$A 13.ª niyel, un monje adquiere una resistencia a conjuros equivalente a su nivel de experiencia + 10. Para poder afectarlo con un sortilegio, el lanzador debe igualar o superar la RC del monje con una prueba de nivel de lanzador (1d20 + el nivel del lanzador; consulta 'Resistencia a conjuros', en la pág. 177).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'alma diamantina' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
insert into class_features (name, clazz, kind, description, source, level)
