where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'alma diamantina' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje');
update class_features set clazz = $c$Monje$c$, kind = $c$Sobrenatural$c$, description = $c$A partir del 15.º nivel, un monje puede crear dentro del cuerpo de otra criatura unas vibraciones que, de así quererlo el monje, pueden resultar letales. El monje puede utilizar esta aptitud una vez a la semana y debe anunciar el intento antes de realizar la tirada de ataque. Constructos, cienos, plantas, muertos vivientes, criaturas incorporales y criaturas inmunes a los golpes críticos son inmunes a este ataque. En los demás casos, si el monje logra impactar y la víctima sufre daño a consecuencia del golpe, se considerará que el ataque de palma temblorosa ha tenido éxito. A partir de ese momento, y hasta haber pasado un día por nivel del monje, éste podrá intentar matar a la víctima cuando lo desee. Para realizar este intento, el monje sólo tiene que desear que el objetivo muera (una acción gratuita), y salvo que este supere un TS de Fortaleza (CD 10 + la mitad del nivel del monje + el modificador de Sabiduría del monje), morirá. Si pasa este tiro, la víctima dejará de estar amenazada por ese ataque de palma temblorosa, 1 pero nada impedirá que resulte afectado por un ataque posterior.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'palma temblorosa' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Palma temblorosa$c$, $c$Monje$c$, $c$Sobrenatural$c$, $c$A partir del 15.º nivel, un monje puede crear dentro del cuerpo de otra criatura unas vibraciones que, de así quererlo el monje, pueden resultar letales. El monje puede utilizar esta aptitud una vez a la semana y debe anunciar el intento antes de realizar la tirada de ataque. Constructos, cienos, plantas, muertos vivientes, criaturas incorporales y criaturas inmunes a los golpes críticos son inmunes a este ataque. En los demás casos, si el monje logra impactar y la víctima sufre daño a consecuencia del golpe, se considerará que el ataque de palma temblorosa ha tenido éxito. A partir de ese momento, y hasta haber pasado un día por nivel del monje, éste podrá intentar matar a la víctima cuando lo desee. Para realizar este intento, el monje sólo tiene que desear que el objetivo muera (una acción gratuita), y salvo que este supere un TS de Fortaleza (CD 10 + la mitad del nivel del monje + el modificador de Sabiduría del monje), morirá. Si pasa este tiro, la víctima dejará de estar amenazada por ese ataque de palma temblorosa, 1 pero nada impedirá que resulte afectado por un ataque posterior.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'palma temblorosa' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje');
update class_features set clazz = $c$Monje$c$, kind = $c$Extraordinaria$c$, description = $c$A partir del nivel 17.º, el monje ya no sufre penalizadores a las características por causa de la edad y tampoco se le puede hacer envejecer utilizando medios mágicos (sin embargo, no se librará de los penalizadores que sufriera de antemano). El personaje seguirá acumulando los bonificadores debidos al envejecimiento y morirá de viejo cuando le llegue la hora. Lengua del sol y la luna (Ex): los monjes de nivel 17.º o superior pueden hablar con cualquier criatura viviente.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'cuerpo eterno' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Cuerpo eterno$c$, $c$Monje$c$, $c$Extraordinaria$c$, $c$A partir del nivel 17.º, el monje ya no sufre penalizadores a las características por causa de la edad y tampoco se le puede hacer envejecer utilizando medios mágicos (sin embargo, no se librará de los penalizadores que sufriera de antemano). El personaje seguirá acumulando los bonificadores debidos al envejecimiento y morirá de viejo cuando le llegue la hora. Lengua del sol y la luna (Ex): los monjes de nivel 17.º o superior pueden hablar con cualquier criatura viviente.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'cuerpo eterno' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje');
update class_features set clazz = $c$Monje$c$, kind = $c$Sobrenatural$c$, description = $c$A partir del nivel 19.º, un monje puede adoptar cada día el estado etéreo durante un asalto por nivel de monje que posea (como el efecto del conjuro etereidad). El personaje podrá volverse etéreo varias veces a lo largo del día, siempre y cuando la cantidad total de asaltos que pase en esa forma no exceda su nivel de monje. Yo perfecto: al alcanzar el 20.º nivel, el monje habrá armonizado de tal manera su cuerpo con sus habilidad y aptitudes cuasimágicas que se convertirá en una criatura mágica. A partir de entonces, se le considerará un ajeno (una criatura de otros planos) y no un humanoide en lo referente a conjuros y efectos mágicos. Por ejemplo, hechizar persona ya no le afecta. Además, el monje gana una reducción del daño de 10/magia; es decir, que ignorará (regenerará instantáneamente) los primeros 10 puntos de daño de todo ataque realizado por un arma no mágica o por un ataque natural realizado por una criatura que no tenga una reducción del daño similar (consulta 'Reducción del daño' en la Guía del Dungeon Master). A diferencia de otros ajenos, el monje sí puede ser devuelto de entre los muertos como si fuese un miembro de su anterior tipo de criatura.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'cuerpo vacio' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Cuerpo vacío$c$, $c$Monje$c$, $c$Sobrenatural$c$, $c$A partir del nivel 19.º, un monje puede adoptar cada día el estado etéreo durante un asalto por nivel de monje que posea (como el efecto del conjuro etereidad). El personaje podrá volverse etéreo varias veces a lo largo del día, siempre y cuando la cantidad total de asaltos que pase en esa forma no exceda su nivel de monje. Yo perfecto: al alcanzar el 20.º nivel, el monje habrá armonizado de tal manera su cuerpo con sus habilidad y aptitudes cuasimágicas que se convertirá en una criatura mágica. A partir de entonces, se le considerará un ajeno (una criatura de otros planos) y no un humanoide en lo referente a conjuros y efectos mágicos. Por ejemplo, hechizar persona ya no le afecta. Además, el monje gana una reducción del daño de 10/magia; es decir, que ignorará (regenerará instantáneamente) los primeros 10 puntos de daño de todo ataque realizado por un arma no mágica o por un ataque natural realizado por una criatura que no tenga una reducción del daño similar (consulta 'Reducción del daño' en la Guía del Dungeon Master). A diferencia de otros ajenos, el monje sí puede ser devuelto de entre los muertos como si fuese un miembro de su anterior tipo de criatura.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'cuerpo vacio' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'monje');
update class_features set clazz = $c$Paladín$c$, kind = $c$Extraordinaria$c$, description = $c$El poder del aura de bien (conulta el conjuro de detectar el bien) del paladín es igual a su nivel en esa clase, igual que sucede con el aura de bien de un clérigo de una deidad buena. Detectar el mal (St): a voluntad, el paladín puede utilizar detectar el mal (como el conjuro).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'aura de bien' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Aura de bien$c$, $c$Paladín$c$, $c$Extraordinaria$c$, $c$El poder del aura de bien (conulta el conjuro de detectar el bien) del paladín es igual a su nivel en esa clase, igual que sucede con el aura de bien de un clérigo de una deidad buena. Detectar el mal (St): a voluntad, el paladín puede utilizar detectar el mal (como el conjuro).$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'aura de bien' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin');
update class_features set clazz = $c$Paladín$c$, kind = $c$Sobrenatural$c$, description = $c$Una vez al día, un paladín puede intentar castigar al mal con un ataque normal de cuerpo a cuerpo; al hacerlo, el personaje añadirá su bonificador de Carisma (en caso de tenerlo) a su tirada de ataque e infligirá un punto de daño adicional por nivel de experiencia que posea. Por ejemplo, un paladín de 13.ª nivel armado con una espada larga infligiría 1d8+13 puntos de daño, además de añadir los posibles bonificadores correspondientes a una Fuerza elevada o a los efectos mágicos que aplicaría normalmente. Si el paladín intentara castigar por accidente a una criatura que no fuera maligna, esta aptitud no surtiría efecto, pero aun así contaría como un intento disponible gastado para ese día. A nivel 5.º y cada cinco niveles adicionales, el paladín puede castigar al mal una vez adicional por día, tal y como se indica en la tabla 3-17: el paladín, hasta un máximo de cinco veces al día a nivel 20.º. | Ataque | | S. de<br>S. de | | S. de | | | - Conjuros diarios -- | | | | | | | | | | | | | | | |--|--| | Nivel | base | Fort. | Ref. | Vol. | Especial | 1.º | 2. | 3.º | 4. | | | | 1.º | +1 | +2 | +0 | +0 | Aura de bien, castigar al mal 1/día detectar el mal | | | | | | | | 2º | +2 | +3 | +0 | +0 | Imposición de manos, gracia divina | | | | | | | | 3° | +3 | +3 | +1 | +1 | Aura de valor, salud divina | | | | | | | | 4. | +4 | +4 | +1 | +1 | Expulsar muertos vivientes | 0 | | | | | | | 5.0 | +5 | +4 | +7 | +1 | Castigar al mal 2/día, montura especial | 0 | | | | | | | 6. | +6/+1 | +5 | +2 | +2 | Quitar enfermedad 1/semana | 1 | | | | | | | 7. | +7/+2 | 45 | +2 | +2 | | | | | | | | | 8.0 | +8/+3 | +6 | +2 | +2 | | | 0 | | | | | | 9. | +9/44 | +6 | +3 | +3 | Quitar enfermedad 2/semana | | 0 | | | | | | 10. | +10/+5 | +7 | +3 | +3 | Castigar al mal 3/día | | | | | | | | 11.º | +11/+6/+1 | +7 | +3 | +3 | | | | 0 | | | | | 12. | +12/+//+2 | +8 | +4 | +4 | Quitar enfermedad 3/semana | | | | | | | | 13. | +13/+8/+3 | 48 | +4 | +4 | | | | | | | | | 14: | +14/+9/+4 | +9 | +4 | +4 | | | | | 0 | | | | 15.º | +15/+10/+5 | +9 | +5 | +15 | Castigar al mal 4/día, quitar enfermedad 4/semana | 2 | | | | | | | 16: | +16/+11/+6/+1 | +10 | +5 | +5 | | 2 | | | | | | | 17. | +17/+12/+7/+2 | +10 | 45 | +5 | | 2 | 2 | 2 | | | | | 18.º | +18/+13/+8/+3 | +77 | +6 | +6 | Quitar enfermedad 5/semana | 3 | N | 2 | 1 | | | | 19. | +19/+14/+9/+4 | +11 | +6 | +6 | | 3 | 3 | 3 | 2 | | | | 20.° | +20/+15/+10/+5 | +12 | +6 | 46 | Castigar al mal 5/día<br>Designed on the comments of the first of the first of the first of the first of the first of | 3 | 3 | 3 | 3 | | | Albandra$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'castigar al mal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Castigar al mal$c$, $c$Paladín$c$, $c$Sobrenatural$c$, $c$Una vez al día, un paladín puede intentar castigar al mal con un ataque normal de cuerpo a cuerpo; al hacerlo, el personaje añadirá su bonificador de Carisma (en caso de tenerlo) a su tirada de ataque e infligirá un punto de daño adicional por nivel de experiencia que posea. Por ejemplo, un paladín de 13.ª nivel armado con una espada larga infligiría 1d8+13 puntos de daño, además de añadir los posibles bonificadores correspondientes a una Fuerza elevada o a los efectos mágicos que aplicaría normalmente. Si el paladín intentara castigar por accidente a una criatura que no fuera maligna, esta aptitud no surtiría efecto, pero aun así contaría como un intento disponible gastado para ese día. A nivel 5.º y cada cinco niveles adicionales, el paladín puede castigar al mal una vez adicional por día, tal y como se indica en la tabla 3-17: el paladín, hasta un máximo de cinco veces al día a nivel 20.º. | Ataque | | S. de<br>S. de | | S. de | | | - Conjuros diarios -- | | | | | | | | | | | | | | | |--|--| | Nivel | base | Fort. | Ref. | Vol. | Especial | 1.º | 2. | 3.º | 4. | | | | 1.º | +1 | +2 | +0 | +0 | Aura de bien, castigar al mal 1/día detectar el mal | | | | | | | | 2º | +2 | +3 | +0 | +0 | Imposición de manos, gracia divina | | | | | | | | 3° | +3 | +3 | +1 | +1 | Aura de valor, salud divina | | | | | | | | 4. | +4 | +4 | +1 | +1 | Expulsar muertos vivientes | 0 | | | | | | | 5.0 | +5 | +4 | +7 | +1 | Castigar al mal 2/día, montura especial | 0 | | | | | | | 6. | +6/+1 | +5 | +2 | +2 | Quitar enfermedad 1/semana | 1 | | | | | | | 7. | +7/+2 | 45 | +2 | +2 | | | | | | | | | 8.0 | +8/+3 | +6 | +2 | +2 | | | 0 | | | | | | 9. | +9/44 | +6 | +3 | +3 | Quitar enfermedad 2/semana | | 0 | | | | | | 10. | +10/+5 | +7 | +3 | +3 | Castigar al mal 3/día | | | | | | | | 11.º | +11/+6/+1 | +7 | +3 | +3 | | | | 0 | | | | | 12. | +12/+//+2 | +8 | +4 | +4 | Quitar enfermedad 3/semana | | | | | | | | 13. | +13/+8/+3 | 48 | +4 | +4 | | | | | | | | | 14: | +14/+9/+4 | +9 | +4 | +4 | | | | | 0 | | | | 15.º | +15/+10/+5 | +9 | +5 | +15 | Castigar al mal 4/día, quitar enfermedad 4/semana | 2 | | | | | | | 16: | +16/+11/+6/+1 | +10 | +5 | +5 | | 2 | | | | | | | 17. | +17/+12/+7/+2 | +10 | 45 | +5 | | 2 | 2 | 2 | | | | | 18.º | +18/+13/+8/+3 | +77 | +6 | +6 | Quitar enfermedad 5/semana | 3 | N | 2 | 1 | | | | 19. | +19/+14/+9/+4 | +11 | +6 | +6 | | 3 | 3 | 3 | 2 | | | | 20.° | +20/+15/+10/+5 | +12 | +6 | 46 | Castigar al mal 5/día<br>Designed on the comments of the first of the first of the first of the first of the first of | 3 | 3 | 3 | 3 | | | Albandra$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'castigar al mal' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin');
update class_features set clazz = $c$Paladín$c$, kind = $c$Sobrenatural$c$, description = $c$A 2.º nivel, un paladín obtiene un bonificador igual a su modificador de Carisma (en caso de ser positivo) en todos sus TS.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'gracia divina' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
