select $c$Gracia divina$c$, $c$Paladín$c$, $c$Sobrenatural$c$, $c$A 2.º nivel, un paladín obtiene un bonificador igual a su modificador de Carisma (en caso de ser positivo) en todos sus TS.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'gracia divina' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin');
update class_features set clazz = $c$Paladín$c$, kind = $c$Sobrenatural$c$, description = $c$Comenzando a 2.º nivel, un paladín con una puntuación de Carisma de 12 o mayor puede curar heridas (las suyas o las de otros) por medio de su toque. Cada día, puede curar una cantidad de puntos de golpe equivalente a su nivel de experiencia multiplicado por su bonificador de Carisma. Por ejemplo, un paladín de 7.º nivel con un Carisma de 16 (bonificador +3) podría curar un máximo de 21 puntos diarios. Un paladín puede dividir su curación entre varias criaturas, y no tiene por qué aprovechar toda su capacidad de una sola vez. Utilizar la imposición de manos es una acción estándar. De manera alternativa, un paladín puede utilizar parte o la totalidad de su poder curativo para infligir daño a criaturas muertas vivientes. Utilizar la imposición de manos de este modo requiere un ataque de toque cuerpo a cuerpo con éxito, y no provoca ataques de oportunidad. El paladín decide cuántos puntos de su asignación diaria desea utilizar como daño después de lograr tocar con éxito a una criatura muerta viviente. Aura de valor: a partir de 3.6 nivel, el paladín es inmune al miedo (mágico o de cualquier otra naturaleza). Todos los aliados que se encuentren a 10' o menos de él ganarán un bonificador +4 de moral en todos sus TS contra efectos de miedo. Esta aptitud funciona mientras el paladín esté consciente, pero no si está inconsciente o muere.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'imposicion de manos' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
