update class_features set clazz = $c$Paladín$c$, kind = $c$Extraordinaria$c$, description = $c$Esta aptitud funciona cuando la montura sufre un ataque que normalmente permitiría un TS de Reflejos para recibir sólo la mitad del daño; si el animal tiene éxito en el tiro no sufrirá daño en absoluto; si falla, sufrirá sólo la mitad del daño.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion mejorada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Evasión mejorada$c$, $c$Paladín$c$, $c$Extraordinaria$c$, $c$Esta aptitud funciona cuando la montura sufre un ataque que normalmente permitiría un TS de Reflejos para recibir sólo la mitad del daño; si el animal tiene éxito en el tiro no sufrirá daño en absoluto; si falla, sufrirá sólo la mitad del daño.$c$, $c$Manual del Jugador 3.5$c$, 0
