update class_features set clazz = $c$Paladín$c$, kind = $c$Sobrenatural$c$, description = $c$El paladín comparte con su montura un vínculo de empatía con un alcance máximo de una milla. El personaje no podrá ver a través de los ojos de su animal, pero ambos podrán comunicarse empáticamente. Ten en cuenta que hasta las monturas inteligentes ven el mundo de forma distinta a los humanos; por tanto, siempre puede haber malentendidos. Debido al vínculo de empatía que hay entre el paladín y su montura, el personaje poseerá la misma relación que su animal con los objetos o lugares, igual que sucede entre un familiar y su amo (consulta 'Familiares', en la pág. 44).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'vinculo de empatia' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Vínculo de empatía$c$, $c$Paladín$c$, $c$Sobrenatural$c$, $c$El paladín comparte con su montura un vínculo de empatía con un alcance máximo de una milla. El personaje no podrá ver a través de los ojos de su animal, pero ambos podrán comunicarse empáticamente. Ten en cuenta que hasta las monturas inteligentes ven el mundo de forma distinta a los humanos; por tanto, siempre puede haber malentendidos. Debido al vínculo de empatía que hay entre el paladín y su montura, el personaje poseerá la misma relación que su animal con los objetos o lugares, igual que sucede entre un familiar y su amo (consulta 'Familiares', en la pág. 44).$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'vinculo de empatia' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin');
update class_features set clazz = $c$Paladín$c$, kind = $c$Extraordinaria$c$, description = $c$La velocidad de la montura aumenta en 10'. Dar órdenes (St): una vez por día por cada dos niveles de paladín de su amo, una montura puede utilizar esta aptitud para dar órdenes a otras criaturas de aproximadamente su especie (en el caso de los caballos y ponis de guerra, esto incluye a burros, mulos y ponís), siempre y cuando el objetivo tenga menos DG que ella. Esta aptitud funciona como el conjuro de orden imperiosa, aunque la montura debe realizar una prueba de Concentración (CD 21) en caso de que alguien cabalgue sobre ella al mismo tiempo (como, por ejemplo, en combate). Si la prueba resulta fallida, la aptitud habrá fracasado, pero el intento contará contra la cantidad máxima de sus usos diarios. Cada objetivo puede intentar una salvación de Vol (CD 10 + la mitad del nivel de paladín + el modificador de Car del paladín) para negar el efecto.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'velocidad mejorada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Velocidad mejorada$c$, $c$Paladín$c$, $c$Extraordinaria$c$, $c$La velocidad de la montura aumenta en 10'. Dar órdenes (St): una vez por día por cada dos niveles de paladín de su amo, una montura puede utilizar esta aptitud para dar órdenes a otras criaturas de aproximadamente su especie (en el caso de los caballos y ponis de guerra, esto incluye a burros, mulos y ponís), siempre y cuando el objetivo tenga menos DG que ella. Esta aptitud funciona como el conjuro de orden imperiosa, aunque la montura debe realizar una prueba de Concentración (CD 21) en caso de que alguien cabalgue sobre ella al mismo tiempo (como, por ejemplo, en combate). Si la prueba resulta fallida, la aptitud habrá fracasado, pero el intento contará contra la cantidad máxima de sus usos diarios. Cada objetivo puede intentar una salvación de Vol (CD 10 + la mitad del nivel de paladín + el modificador de Car del paladín) para negar el efecto.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'velocidad mejorada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin');
update class_features set clazz = $c$Paladín$c$, kind = $c$Extraordinaria$c$, description = $c$La resistencia a conjuros de la montura equivale al nivel de experiencia de paladín de su amo +5. Para afectar a la montura con un conjuro, el lanzador debe realizar una prueba de nivel de lanzador (1d20 + nivel del lanzador) que iguale o supere a la resistencia a conjuros del animal.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'resistencia a conjuros' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Resistencia a conjuros$c$, $c$Paladín$c$, $c$Extraordinaria$c$, $c$La resistencia a conjuros de la montura equivale al nivel de experiencia de paladín de su amo +5. Para afectar a la montura con un conjuro, el lanzador debe realizar una prueba de nivel de lanzador (1d20 + nivel del lanzador) que iguale o supere a la resistencia a conjuros del animal.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'resistencia a conjuros' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin');
update class_features set clazz = $c$Paladín$c$, kind = $c$Extraordinaria$c$, description = $c$A 3.5 nivel, un paladín se vuelve inmune a todas las enfermedades, incluyendo las enfermedades sobrenaturales y mágicas (como la putridez de momia y la licantropía).$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'salud divina' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Salud divina$c$, $c$Paladín$c$, $c$Extraordinaria$c$, $c$A 3.5 nivel, un paladín se vuelve inmune a todas las enfermedades, incluyendo las enfermedades sobrenaturales y mágicas (como la putridez de momia y la licantropía).$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'salud divina' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin');
update class_features set clazz = $c$Paladín$c$, kind = $c$Sobrenatural$c$, description = $c$Cuando un paladín llega al 4.º nivel, adquiere la aptitud sobrenatural de expulsar muertos vivientes, pudiendo usarla cada día un número de veces igual a 3 + su modificador de Carisma. Los paladines expulsan muertos vivientes como lo haría un clérigo con tres niveles menos (consulta 'Expulsar y reprender muertos vivientes', en la pág. 156). Conjuros: a partir del 4.º nivel, un paladín adquiere la aptitud de lanzar una pequeña cantidad de conjuros de magia divina (el mismo tipo disponible para los clérigos, druidas y exploradores), elegidos de la lista de conjuros de paladín (pág. 195). Un paladín debe elegir y preparar sus conjuros con antelación. Para preparar o lanzar un sortilegio, el personaje ha de tener una puntuación en Sabiduría de al menos 10 + el nivel del conjuro (Sab 11 para conjuros de 1.5 nivel, Sab 12 para conjuros de 2.º nivel, etc). La CD para los TS contra los conjuros de paladín es 10 + el nivel del conjuro + el modificador de Sabiduría del paladín. Como otros lanzadores de conjuros, un paladín sólo puede lanzar un número determinado de conjuros de cada nivel por día. Su asignación diaria de conjuros figura en la tabla 3-17: el paladín. Además, recibe conjuros diarios adicionales si tiene una puntuación alta de Sabiduría (ver la tabla 1-1: modificadores de característica y conjuros adicionales, pág. 8). Cuando la tabla 3-17 indica que el paladín obtiene 0 conjuros por día de un determinado nivel de conjuros (por ejemplo, conjuros de 1.ª nivel para un paladín de 4.º nivel), solamente obtiene los conjuros adicionales para ese nivel correspondientes a su puntuación de Sabiduría. A diferencia del clérigo, un paladín no tiene acceso a ningún conjuro ni poder garantizado de dominio. Un paladín prepara y lanza conjuros del mismo modo que lo hace un clérigo, aunque no puede perder un conjuro preparado para lanzar un conjuro de curar en su lugar. Un paladín puede preparar y lanzar cualquier conjuro de la lista de conjuros de paladín (pág. 195), suponiendo que pueda lanzar conjuros de ese nivel, aunque durante la meditación de ese día deberá elegir qué conjuros va a preparar. Aunque hasta el 3.6 nivel el paladín carece de nivel de lanzador, a partir del 4.º este valor equivaldrá a la mitad del nivel de paladín poseído por el personaje. Montura especial (St): al llegar a 5.º nivel, un paladín obtiene el servicio de un leal corcel, de fuerza e inteligencia insólitas, que le ayudará en su cruzada contra el mal (consulta la barra lateral). Normalmente, esta montura será un caballo de guerra pesado (si el paladín es de tamaño Mediano) o un poni de guerra (si es Pequeño). Una vez al día, como acción de asalto completo, un paladín puede llamar a su montura de los reinos celestiales en los que reside. La montura aparece inmediatamente junto al paladín y permanece durante dos horas por nivel del mismo. Puede ser despedida en cualquier momento como acción gratuita. La montura que es convocada siempre es la misma criatura, aunque el paladín puede liberar a una montura determinada de su servicio (si se ha hecho demasiado vieja como para unirse a su cruzada, por ejemplo). Cada vez que es llamada, la montura aparece totalmente sana, sin importar el daño que pudiera haber recibido previamente. Además, la montura aparece llevando o transportando cualquier cosa que tuviese al ser despedida (incluyendo barda, silla de montar, alforjas, etc). Llamar a una montura es un efecto de conjuración (llamada). Si la montura del paladín muere, desaparece al instante, dejando tras de sí cualquier equipo que transportara. El paladín no puede convocar a otra montura durante treinta días o hasta que obtenga un nuevo nivel de paladín, lo que suceda primero, incluso aunque la montura sea devuelta a la vida de algún modo. Durante este periodo de treinta días, el paladín recibe un penalizador -1 a las tiradas de ataque y daño con armas. Quitar enfermedad (St): a 6.º nivel, un paladín puede producir un efecto de quitar enfermedad (igual que si usara el conjuro del mismo nombre) una vez a la semana. Puede utilizar esta aptitud una vez adicional por semana por cada tres niveles posteriores al 6.º (dos veces por semana a 9.º, tres veces a 12.º, etc.). Código de conducta: un paladín ha de ser de alineamiento legal bueno y perderá todas sus aptitudes especiales de clase si realiza voluntaria- mente cualquier acto maligno. Además, el código del paladín exige que respete toda autoridad legítima, que actúe con honor (sin mentir, engañar, utilizar venenos, etc.), que ayude a los necesitados (siempre y cuando éstos no empleen la ayuda para fines maléficos o caóticos) y que castigue a los que hagan daño o amenacen a los inocentes. Acompañantes: aunque un paladín puede ir de aventuras con personajes de cualquier alineamiento neutral o bueno, jamás se asociará a sabiendas con gente maligna. Además, no continuará relacionándose con nadie que atente continuamente contra su código moral. Un paladín sólo contratará personal o aceptará seguidores si esas personas son de alineamiento legal bueno.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'expulsar muertos vivientes' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Expulsar muertos vivientes$c$, $c$Paladín$c$, $c$Sobrenatural$c$, $c$Cuando un paladín llega al 4.º nivel, adquiere la aptitud sobrenatural de expulsar muertos vivientes, pudiendo usarla cada día un número de veces igual a 3 + su modificador de Carisma. Los paladines expulsan muertos vivientes como lo haría un clérigo con tres niveles menos (consulta 'Expulsar y reprender muertos vivientes', en la pág. 156). Conjuros: a partir del 4.º nivel, un paladín adquiere la aptitud de lanzar una pequeña cantidad de conjuros de magia divina (el mismo tipo disponible para los clérigos, druidas y exploradores), elegidos de la lista de conjuros de paladín (pág. 195). Un paladín debe elegir y preparar sus conjuros con antelación. Para preparar o lanzar un sortilegio, el personaje ha de tener una puntuación en Sabiduría de al menos 10 + el nivel del conjuro (Sab 11 para conjuros de 1.5 nivel, Sab 12 para conjuros de 2.º nivel, etc). La CD para los TS contra los conjuros de paladín es 10 + el nivel del conjuro + el modificador de Sabiduría del paladín. Como otros lanzadores de conjuros, un paladín sólo puede lanzar un número determinado de conjuros de cada nivel por día. Su asignación diaria de conjuros figura en la tabla 3-17: el paladín. Además, recibe conjuros diarios adicionales si tiene una puntuación alta de Sabiduría (ver la tabla 1-1: modificadores de característica y conjuros adicionales, pág. 8). Cuando la tabla 3-17 indica que el paladín obtiene 0 conjuros por día de un determinado nivel de conjuros (por ejemplo, conjuros de 1.ª nivel para un paladín de 4.º nivel), solamente obtiene los conjuros adicionales para ese nivel correspondientes a su puntuación de Sabiduría. A diferencia del clérigo, un paladín no tiene acceso a ningún conjuro ni poder garantizado de dominio. Un paladín prepara y lanza conjuros del mismo modo que lo hace un clérigo, aunque no puede perder un conjuro preparado para lanzar un conjuro de curar en su lugar. Un paladín puede preparar y lanzar cualquier conjuro de la lista de conjuros de paladín (pág. 195), suponiendo que pueda lanzar conjuros de ese nivel, aunque durante la meditación de ese día deberá elegir qué conjuros va a preparar. Aunque hasta el 3.6 nivel el paladín carece de nivel de lanzador, a partir del 4.º este valor equivaldrá a la mitad del nivel de paladín poseído por el personaje. Montura especial (St): al llegar a 5.º nivel, un paladín obtiene el servicio de un leal corcel, de fuerza e inteligencia insólitas, que le ayudará en su cruzada contra el mal (consulta la barra lateral). Normalmente, esta montura será un caballo de guerra pesado (si el paladín es de tamaño Mediano) o un poni de guerra (si es Pequeño). Una vez al día, como acción de asalto completo, un paladín puede llamar a su montura de los reinos celestiales en los que reside. La montura aparece inmediatamente junto al paladín y permanece durante dos horas por nivel del mismo. Puede ser despedida en cualquier momento como acción gratuita. La montura que es convocada siempre es la misma criatura, aunque el paladín puede liberar a una montura determinada de su servicio (si se ha hecho demasiado vieja como para unirse a su cruzada, por ejemplo). Cada vez que es llamada, la montura aparece totalmente sana, sin importar el daño que pudiera haber recibido previamente. Además, la montura aparece llevando o transportando cualquier cosa que tuviese al ser despedida (incluyendo barda, silla de montar, alforjas, etc). Llamar a una montura es un efecto de conjuración (llamada). Si la montura del paladín muere, desaparece al instante, dejando tras de sí cualquier equipo que transportara. El paladín no puede convocar a otra montura durante treinta días o hasta que obtenga un nuevo nivel de paladín, lo que suceda primero, incluso aunque la montura sea devuelta a la vida de algún modo. Durante este periodo de treinta días, el paladín recibe un penalizador -1 a las tiradas de ataque y daño con armas. Quitar enfermedad (St): a 6.º nivel, un paladín puede producir un efecto de quitar enfermedad (igual que si usara el conjuro del mismo nombre) una vez a la semana. Puede utilizar esta aptitud una vez adicional por semana por cada tres niveles posteriores al 6.º (dos veces por semana a 9.º, tres veces a 12.º, etc.). Código de conducta: un paladín ha de ser de alineamiento legal bueno y perderá todas sus aptitudes especiales de clase si realiza voluntaria- mente cualquier acto maligno. Además, el código del paladín exige que respete toda autoridad legítima, que actúe con honor (sin mentir, engañar, utilizar venenos, etc.), que ayude a los necesitados (siempre y cuando éstos no empleen la ayuda para fines maléficos o caóticos) y que castigue a los que hagan daño o amenacen a los inocentes. Acompañantes: aunque un paladín puede ir de aventuras con personajes de cualquier alineamiento neutral o bueno, jamás se asociará a sabiendas con gente maligna. Además, no continuará relacionándose con nadie que atente continuamente contra su código moral. Un paladín sólo contratará personal o aceptará seguidores si esas personas son de alineamiento legal bueno.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'expulsar muertos vivientes' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'paladin');
update class_features set clazz = $c$Pícaro$c$, kind = $c$Extraordinaria$c$, description = $c$A 2.º nivel y posteriores, un pícaro puede evitar incluso los ataques mágicos e inusuales con su gran agilidad. Desde ese momento, no sufrirá daño alguno cuando tenga éxito en un TS de Reflejos contra un ataque que normalmente infligiría la mitad del daño con un tiro con éxito (como el terrible aliento de un dragón rojo o una bola de fuego). Esta apti- tud extraordinaria sólo puede utilizarse cuando el pícaro viste armadura ligera o ninguna armadura en absoluto. Un pícaro indefenso (inconsciente o paralizado, por ejemplo) no puede beneficiarse de la evasión.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Evasión$c$, $c$Pícaro$c$, $c$Extraordinaria$c$, $c$A 2.º nivel y posteriores, un pícaro puede evitar incluso los ataques mágicos e inusuales con su gran agilidad. Desde ese momento, no sufrirá daño alguno cuando tenga éxito en un TS de Reflejos contra un ataque que normalmente infligiría la mitad del daño con un tiro con éxito (como el terrible aliento de un dragón rojo o una bola de fuego). Esta apti- tud extraordinaria sólo puede utilizarse cuando el pícaro viste armadura ligera o ninguna armadura en absoluto. Un pícaro indefenso (inconsciente o paralizado, por ejemplo) no puede beneficiarse de la evasión.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro');
update class_features set clazz = $c$Pícaro$c$, kind = $c$Extraordinaria$c$, description = $c$A 3.6 nivel, un pícaro obtiene un sentido intuitivo que le advierte de las trampas, lo que le concede un bonificador +1 a los TS de Reflejos realizados a fin de evitarlas, y un bonificador +1 de esquiva a la CA contra los ataques procedentes de ellas. Estos bonificadores aumentan en +2 cuando el personaje alcanza 6.º nivel, a +3 cuando alcanza 9.º nivel, a +4 cuando llega a 12.º, a +5 a nivel 15.º y finalmente a +6 a nivel 18.º. Los bonificadores de sentido de las trampas obtenidos de diferentes clases se apilan.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'sentido de las trampas' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Sentido de las trampas$c$, $c$Pícaro$c$, $c$Extraordinaria$c$, $c$A 3.6 nivel, un pícaro obtiene un sentido intuitivo que le advierte de las trampas, lo que le concede un bonificador +1 a los TS de Reflejos realizados a fin de evitarlas, y un bonificador +1 de esquiva a la CA contra los ataques procedentes de ellas. Estos bonificadores aumentan en +2 cuando el personaje alcanza 6.º nivel, a +3 cuando alcanza 9.º nivel, a +4 cuando llega a 12.º, a +5 a nivel 15.º y finalmente a +6 a nivel 18.º. Los bonificadores de sentido de las trampas obtenidos de diferentes clases se apilan.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'sentido de las trampas' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro');
update class_features set clazz = $c$Pícaro$c$, kind = $c$Extraordinaria$c$, description = $c$A 4.º nivel, el pícaro adquiere la apti- tud de reaccionar ante el peligro antes de lo que sus sentidos le permitirían normalmente. Por ello retiene su bonificador de Destreza a la CA (en caso de tenerlo) incluso aunque le tomen desprevenido o sea atacado por un enemigo invisible. A pesar de ello seguirá perdiendo el bonificador de Destreza a la CA en caso de quedar inmovilizado. Si un pícaro ya poseía esquiva asombrosa de una clase diferente (un picaro con al menos dos niveles de bárbaro, por ejemplo), automáticamente obtiene esquiva asombrosa mejorada (ver más adelante) en su lugar.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'esquiva asombrosa' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro';
