update class_features set clazz = $c$Pícaro$c$, kind = $c$Extraordinaria$c$, description = $c$Esta aptitud funciona igual que la evasión, aunque es más beneficiosa: el pícaro seguirá sin sufrir daño al pasar un TS contra ataques como el arma de aliento de un dragón o una bola de fuego, pero a partir de ahora sólo sufrirá la mitad de daño aunque falle las tiradas (los reflejos del personaje le permitirán apartarse del peligro con increíble velocidad). Un pícaro indefenso (inconsciente o paralizado, por ejemplo) no se puede beneficiar de la evasión mejorada.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'evasion mejorada' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro';
