where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'lisiar con un impacto' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro');
update class_features set clazz = $c$Pícaro$c$, kind = $c$Extraordinaria$c$, description = $c$Esta aptitud representa la capacidad del pícaro de librarse de los efectos mágicos que puedan controlarlo u obligarle a obrar de una forma concreta. Cuando un pícaro con mente escurridiza es afectado por un encantamiento y falla su TS, puede intentar salvar de nuevo un asalto después con la misma CD. Sólo dispone de esta oportunidad adicional.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'mente escurridiza' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro';
insert into class_features (name, clazz, kind, description, source, level)
select $c$Mente escurridiza$c$, $c$Pícaro$c$, $c$Extraordinaria$c$, $c$Esta aptitud representa la capacidad del pícaro de librarse de los efectos mágicos que puedan controlarlo u obligarle a obrar de una forma concreta. Cuando un pícaro con mente escurridiza es afectado por un encantamiento y falla su TS, puede intentar salvar de nuevo un asalto después con la misma CD. Sólo dispone de esta oportunidad adicional.$c$, $c$Manual del Jugador 3.5$c$, 0
where not exists (select 1 from class_features where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'mente escurridiza' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro');
update class_features set clazz = $c$Pícaro$c$, kind = $c$Extraordinaria$c$, description = $c$Una vez por asalto, el pícaro puede realizar un ataque de oportunidad contra un oponente al que otro personaje acaba de infligir daño de cuerpo a cuerpo. Este golpe se considerará el ataque de oportunidad del pícaro durante el asalto en curso. Ni siquiera un pícaro con la dote Reflejos de combate podrá utilizar la aptitud de oportunismo más de una vez por asalto. Rodar a la defensiva (Ex); el pícaro puede echar a rodar para apartarse de un golpe potencialmente mortal y hacer que éste le inflija menos daño. Una vez al día, cuando los puntos de golpe del pícaro vayan a quedar reducidos a 0 o menos en combate (por culpa de un arma u otro tipo de golpe, no por un conjuro ni por una aptitud especial), el personaje puede intentar echarse a rodar para sufrir menos daño; hará un TS Reflejos (CD = daño sufrido) y, en caso de tener éxito, sólo perderá la mitad de puntos de golpe indicados en la tirada de daño. Para poder rodar a la defensiva el pícaro tiene que ser consciente del ataque y debe poder reaccionar ante él; si no dispusiera de su bonificador de Destreza, le resultaría imposible utilizar esta aptitud. Ya que este efecto normalmente no permite que el pícaro haga TS de Reflejos para sufrir sólo la mitad del daño, la aptitud de evasión no podrá aplicarse cuando un pícaro ruede a la defensiva. Dote: el pícaro puede ganar una dote en lugar de una aptitud especial.$c$, source = $c$Manual del Jugador 3.5$c$ where lower(translate(name, 'áéíóúüñ', 'aeiouun')) = 'oportunismo' and lower(translate(clazz, 'áéíóúüñ', 'aeiouun')) = 'picaro';
insert into class_features (name, clazz, kind, description, source, level)
